const toLocalISO = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
const todayISO = () => toLocalISO(new Date());

// meno.priezvisko@matecoslovakia.sk — odstráni diakritiku, zmení na malé písmená
function nameToEmail(fullName, domain = "matecoslovakia.sk") {
  if (!fullName) return "";
  const clean = fullName
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // odstráni diakritiku
    .trim();
  const parts = clean.split(/\s+/).filter(Boolean);
  if (parts.length < 2) return `${clean.toLowerCase()}@${domain}`;
  const first = parts[0].toLowerCase();
  const last = parts[parts.length - 1].toLowerCase();
  return `${first}.${last}@${domain}`;
}

/* ---------------------------------------------------------
   Email — hybridné odosielanie (Outlook Web / mailto pre desktop platformu
   alebo mobil). Platforma si zapamätá voľbu v prehliadači (localStorage).
--------------------------------------------------------- */
const MAIL_PREF_KEY = "mateco_mail_client_pref"; // "web" | "desktop"
let _mailComposeListener = null;
function setMailComposeListener(fn) {
  _mailComposeListener = fn;
}
function buildMailtoUrl({ to, cc, subject, body }) {
  const parts = [];
  if (cc) parts.push(`cc=${encodeURIComponent(cc)}`);
  if (subject) parts.push(`subject=${encodeURIComponent(subject)}`);
  if (body) parts.push(`body=${encodeURIComponent(body)}`);
  const qs = parts.join("&");
  return `mailto:${to || ""}${qs ? "?" + qs : ""}`;
}
function buildOutlookWebUrl({ to, cc, subject, body }) {
  const parts = [`path=${encodeURIComponent("/mail/action/compose")}`];
  if (to) parts.push(`to=${encodeURIComponent(to)}`);
  if (cc) parts.push(`cc=${encodeURIComponent(cc)}`);
  if (subject) parts.push(`subject=${encodeURIComponent(subject)}`);
  if (body) parts.push(`body=${encodeURIComponent(body)}`);
  return `https://outlook.office.com/mail/deeplink/compose?${parts.join("&")}`;
}
function sendMailWithClient(client, mail) {
  if (client === "web") {
    window.open(buildOutlookWebUrl(mail), "_blank");
  } else {
    window.location.href = buildMailtoUrl(mail);
  }
}
// Zavolajte odkiaľkoľvek v platforme: ak už platforma pozná preferenciu, mail sa
// rovno otvorí; inak sa najprv opýta (a odpoveď si zapamätá).
function composeMail(mail) {
  let pref = null;
  try {
    pref = localStorage.getItem(MAIL_PREF_KEY);
  } catch (e) {
    console.error("localStorage nedostupný, platforma sa opýta znova", e);
  }
  if (pref === "web" || pref === "desktop") {
    sendMailWithClient(pref, mail);
  } else if (_mailComposeListener) {
    _mailComposeListener(mail);
  } else {
    console.error("composeMail: mailComposeListener ešte nie je zaregistrovaný");
  }
}

const addDaysISO = (iso, days) => {
  const d = new Date(iso + "T00:00:00");
  const shifted = new Date(d.getTime() + days * 86400000);
  return toLocalISO(shifted);
};
// Pre porovnanie období v štatistikách — vráti rovnako dlhé obdobie hneď pred
// zvoleným (napr. 1.–15. jún → predchádzajúce je 17.–31. máj).
function previousPeriod(start, end) {
  const days = Math.round((new Date(end + "T00:00:00") - new Date(start + "T00:00:00")) / 86400000) + 1;
  const prevEnd = addDaysISO(start, -1);
  const prevStart = addDaysISO(prevEnd, -(days - 1));
  return { start: prevStart, end: prevEnd };
}
// Zostaví údaj pre StatCard — porovná aktuálnu hodnotu s predchádzajúcim
// obdobím a vráti smer (hore/dole/rovnako) aj čitateľný text.
function statDelta(current, previous, { percent } = {}) {
  if (previous === 0 && current === 0) return { direction: "flat", text: "bez zmeny" };
  if (previous === 0) return { direction: "up", text: percent ? `+${current} b. p. oproti 0` : `+${current} oproti 0` };
  const diff = current - previous;
  const pct = Math.round((diff / previous) * 100);
  const direction = diff > 0 ? "up" : diff < 0 ? "down" : "flat";
  const sign = diff > 0 ? "+" : "";
  return { direction, text: percent ? `${sign}${diff} b. p. oproti minulému obdobiu` : `${sign}${pct}% oproti minulému obdobiu` };
}
// Posunie dátum o celé roky, zachová mesiac/deň — presne to, čo potrebuje
// úradná skúška (platí vždy 10 rokov od dňa, keď sa vykonala).
const addYearsISO = (iso, years) => {
  const [y, m, d] = iso.split("-");
  return `${Number(y) + years}-${m}-${d}`;
};
function compressDates(dates) {
  const sorted = [...dates].sort();
  if (sorted.length === 0) return "";
  const ranges = [];
  let start = sorted[0], prev = sorted[0];
  for (let i = 1; i < sorted.length; i++) {
    const d = sorted[i];
    if (d === addDaysISO(prev, 1)) { prev = d; continue; }
    ranges.push(start === prev ? fmtDate(start) : `${fmtDate(start)}–${fmtDate(prev)}`);
    start = d; prev = d;
  }
  ranges.push(start === prev ? fmtDate(start) : `${fmtDate(start)}–${fmtDate(prev)}`);
  return ranges.join(", ");
}
function weekRangeFor(iso) {
  const d = new Date(iso + "T00:00:00");
  const dow = d.getDay();
  const mondayOffset = dow === 0 ? -6 : 1 - dow;
  const weekStart = addDaysISO(iso, mondayOffset);
  const weekEnd = addDaysISO(weekStart, 6);
  return { weekStart, weekEnd };
}
const fmtDate = (iso) => {
  if (!iso) return "—";
  const [y, m, d] = iso.split("T")[0].split("-");
  return `${d}.${m}.${y}`;
};
const daysBetween = (a, b) => {
  const d1 = new Date(a + "T00:00:00");
  const d2 = new Date(b + "T00:00:00");
  return Math.round((d2 - d1) / 86400000);
};
const uid = () => Math.random().toString(36).slice(2, 10) + Date.now().toString(36).slice(-4);
// ERP tok (checklisty kontrolóra aj servisné protokoly): keď je záznam už
// označený ako spracovaný (erpProcessed) a niektoré zo sledovaných polí sa
// zmení oproti snímke z momentu spracovania (erpSnapshot), automaticky sa
// vráti medzi nespracované — fakturant sa to inak nedozvie a nahral by do
// ERP staré číslo. Vracia buď {} (nič sa nemení) alebo { erpProcessed: false }.
function revertErpIfChanged(record, patch, fields) {
  if (!record?.erpProcessed || !record.erpSnapshot) return {};
  const changed = fields.some((f) => JSON.stringify(patch[f] ?? record[f]) !== JSON.stringify(record.erpSnapshot[f]));
  return changed ? { erpProcessed: false } : {};
}

function effectiveStatus(job, today) {
  if (!job) return null;
  if (job.status === "completed") return "completed";
  if (today < job.startDate) return "planned";
  if (job.endDate && today > job.endDate) return "overdue";
  return "active";
}

function currentJobFor(jobs, machineId, today) {
  const candidates = jobs
    .filter((j) => j.machineId === machineId && j.status !== "completed")
    .filter((j) => j.startDate <= today)
    .sort((a, b) => (a.startDate < b.startDate ? 1 : -1));
  return candidates[0] || null;
}
// Aktuálne miesto stroja PRÁVE TERAZ — podľa bežiacej zákazky, inak podľa depa.
// Používa sa všade, kde sa má zobrazovať živá poloha (poškodenia, revízie, úradné
// skúšky, plán servisu), namiesto adresy "zamrznutej" v momente nahlásenia.
function machineCurrentLocation(machine) {
  if (!machine) return "";
  return machine.currentJob?.toLocation || machine.depo || "";
}
// Depo, z ktorého bol stroj vypravený — na rozdiel od machineCurrentLocation (živé
// MIESTO zákazky, napr. u zákazníka) toto vracia DEPO zodpovedné za stroj, aj keď je
// práve na zákazke von. Používa sa na filtrovanie podľa depa (napr. v Poškodeniach
// strojov požičovne), kde "miesto zákazky" nie je zo zoznamu diep a filter by inak
// stroje na zákazke von ticho vyradil.
function machineDispatchDepo(machine) {
  if (!machine) return "";
  return machine.currentJob?.fromDepo || machine.depo || "";
}
// To isté pre priradenia v Pláne servisu — uprednostní živú polohu stroja (ak ho
// vieme dohľadať), inak sa vráti k pôvodne uloženej hodnote (napr. rýchle udalosti
// bez stroja, alebo externý stroj mimo evidencie).
function assignmentLocation(a, machineById) {
  if (a.machineId) {
    const live = machineCurrentLocation(machineById?.[a.machineId]);
    if (live) return live;
  }
  return a.umiestnenie || "";
}
// Kto a kedy smie reálne vypísať danú fázu protokolu o odovzdaní/prevzatí — len
// šofér PRIDELENÝ na daný vývoz/zvoz, a len V DEŇ, kedy sa vývoz/zvoz reálne deje.
// Ak zákazka nemá určený dátum konca (bez konca), platforma pri vrátení nevie kontrolovať
// deň dopredu — kontroluje sa vtedy už len to, že ide o prideleného šoféra.
// Vlastní šoféri prví, externí (subdodávateľské firmy) oddelene pod vlastnou
// skupinou — nech sa v zozname na priradenie nemiešajú medzi seba.
function driverOptionsGrouped(drivers) {
  const active = drivers.filter((d) => !d.archived);
  const internal = active.filter((d) => d.role !== "externy_sofer");
  const external = active.filter((d) => d.role === "externy_sofer");
  return (
    <>
      {internal.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
      {external.length > 0 && (
        <optgroup label="Externé prepravy">
          {external.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
        </optgroup>
      )}
    </>
  );
}

function canFillHandoverPhase(job, myEmployee, phase, user) {
  // Rola sa overuje podľa profilu (user.role), nie podľa employees.role — ten
  // sa od profilu môže rozísť (rovnaký problém, aký spôsobil, že šofér
  // nevidel svoje priradené prevozy — viď transportNotes).
  if (!job || !myEmployee || !user || (user.role !== "sofer" && user.role !== "externy_sofer")) return false;
  const today = todayISO();
  if (phase === "prevzatie") {
    // Skutočný deň vývozu je departureDate (dá sa prepísať nezávisle od
    // zmluvného startDate, napr. pri odloženom vývoze) — ak nie je zadaný,
    // spadá sa na startDate.
    return job.driverId === myEmployee.id && (job.departureDate || job.startDate) === today;
  }
  // Vrátenie stroja dáva zmysel riešiť len na reálne ukončenej zákazke — inak by
  // šofér mohol dokončiť protokol o vrátení aj na aktívnej zákazke, napr. keď
  // dispečer ukončenie predtým zrušil a zákazka sa vrátila do aktívneho stavu.
  if (job.status !== "completed") return false;
  // Rovnako pickupDate (skutočný deň zvozu) namiesto zmluvného endDate.
  const effectiveEndDate = job.pickupDate || job.endDate;
  const dateOk = !effectiveEndDate || effectiveEndDate === today;
  return job.returnDriverId === myEmployee.id && dateOk;
}
function nextJobFor(jobs, machineId, today) {
  const candidates = jobs
    .filter((j) => j.machineId === machineId && j.status !== "completed")
    .filter((j) => j.startDate > today)
    .sort((a, b) => (a.startDate > b.startDate ? 1 : -1));
  return candidates[0] || null;
}

