function DocumentsView({
  subView,
  subTabs,
  framoveZmluvy,
  blacklist,
  customers,
  onAddFramovaZmluva,
  onImportFramoveZmluvy,
  onDeleteFramovaZmluva,
  onAddBlacklist,
  onImportBlacklist,
  onDeleteBlacklist,
  canEdit,
}) {
  const active = subTabs.find((s) => s.id === subView);

  if (subView === "ramcove-zmluvy") {
    return (
      <RecordsTableView
        title="Zoznam rámcových zmlúv"
        fields={FRAMOVA_ZMLUVA_FIELDS}
        items={framoveZmluvy}
        onAdd={onAddFramovaZmluva}
        onImport={onImportFramoveZmluvy}
        onDelete={onDeleteFramovaZmluva}
        canEdit={canEdit}
        recordLabel="rámcovú zmluvu"
        customers={customers}
        customerNameKey="najomca"
      />
    );
  }
  if (subView === "blacklist") {
    return (
      <RecordsTableView
        title="BLACKLIST zákazníkov"
        fields={BLACKLIST_FIELDS}
        items={blacklist}
        onAdd={onAddBlacklist}
        onImport={onImportBlacklist}
        onDelete={onDeleteBlacklist}
        canEdit={canEdit}
        recordLabel="blacklistovaného zákazníka"
        customers={customers}
        customerNameKey="nazovZakaznika"
      />
    );
  }

  return (
    <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>
      {active ? (
        <>Sekcia "{active.label}" sa pripravuje.</>
      ) : (
        <>Táto sekcia sa pripravuje — podzáložky pribudnú čoskoro.</>
      )}
    </div>
  );
}


function GlobalSearch({ searchIndex, onNavigate }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const boxRef = useRef(null);

  useEffect(() => {
    function onDocClick(e) {
      if (boxRef.current && !boxRef.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, []);

  const q = query.trim().toLowerCase();
  const results =
    q.length < 2
      ? []
      : (searchIndex || [])
          .filter((r) => r.searchText.includes(q))
          .slice(0, 8);

  return (
    <div ref={boxRef} className="global-search-box" style={{ position: "relative", width: "100%", maxWidth: 480, minWidth: 200 }}>
      <input
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        placeholder="Hľadať stroj, zákazku, zákazníka, poškodenie..."
        style={{
          width: "100%",
          border: "1px solid rgba(0,0,0,.1)",
          background: "var(--panel-2)",
          color: "var(--text)",
          borderRadius: 6,
          padding: "5px 10px",
          fontSize: 13,
          outline: "none",
        }}
      />
      {open && q.length >= 2 && (
        <div
          className="panel"
          style={{
            position: "absolute",
            top: "calc(100% + 4px)",
            left: 0,
            width: 340,
            maxWidth: "80vw",
            maxHeight: 380,
            overflowY: "auto",
            zIndex: 200,
            padding: 6,
          }}
        >
          {results.length === 0 ? (
            <div style={{ padding: 10, fontSize: 13, color: "var(--text-dim)" }}>Žiadne výsledky.</div>
          ) : (
            results.map((r) => (
              <div
                key={r.type + r.id}
                onClick={() => {
                  onNavigate(r);
                  setQuery("");
                  setOpen(false);
                }}
                style={{
                  padding: "8px 10px",
                  borderRadius: 6,
                  cursor: "pointer",
                  borderBottom: "1px solid var(--border)",
                }}
                onMouseDown={(e) => e.preventDefault()}
              >
                <div style={{ fontSize: 11, color: "var(--accent)", fontWeight: 700, textTransform: "uppercase" }}>{r.kindLabel}</div>
                <div style={{ fontSize: 14, fontWeight: 600 }}>{r.title}</div>
                {r.subtitle && <div style={{ fontSize: 12, color: "var(--text-dim)" }}>{r.subtitle}</div>}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

// Skratky modulov v úzkom IconRail páse — písmená namiesto SVG ikon (lepšie
// čitateľné v tak úzkom stĺpci ako samostatné piktogramy).
const MODULE_SHORT_LABEL = { poziciovna: "POŽ", servis: "SRV", administrativa: "ADM" };

// Zoznam modulov + ich záložiek — zdieľané medzi bočným menu na mobile
// (SidebarNav, vnútri výsuvnej zásuvky) a ikonovým pásom na webe (IconRail),
// nech sa tabuľka záložiek nemusí udržiavať na dvoch miestach naraz.
function buildNavModules(effectiveUser, damageAlertCount) {
  const poziciovnaTabs = [
    { id: "calendar", label: "Kalendár" },
    { id: "jobs", label: "Zákazky" },
    { id: "prepravy", label: "Prepravy" },
    { id: "dashboard", label: "Stroje" },
    { id: "drivers", label: "Šoféri" },
    { id: "customers", label: "Zákazníci" },
    ...(can(effectiveUser, "erp_pozicovna_view") ? [{ id: "erp_pozicovna", label: "ERP podklady" }] : []),
    { id: "dokumenty", label: "Dokumenty", dropdown: true },
  ];
  const servisTabs = [
    { id: "prehlad", label: "Prehľad" },
    { id: "plan", label: "Plán servisu" },
    { id: "diely", label: "Náhradné diely" },
    { id: "poskodenia", label: "Poškodenia strojov požičovne" },
    { id: "externe", label: "Externé servisné zákazky" },
    { id: "revizie", label: "Revízie" },
    { id: "uradne_skusky", label: "Úradné skúšky" },
    ...(can(effectiveUser, "erp_view") ? [{ id: "erp", label: "ERP — kontroly" }] : []),
    { id: "dokumenty", label: "Dokumenty", dropdown: true },
  ];
  const administrativaTabs = [
    ...(can(effectiveUser, "statistics_view") ? [{ id: "statistiky", label: "Štatistiky" }] : []),
    { id: "modely", label: "Modely strojov" },
    { id: "zamestnanci", label: "Zamestnanci" },
    { id: "checkeri", label: "Checkeri podľa depa" },
    ...(can(effectiveUser, "vehicle_manage") ? [{ id: "auta", label: "Autá" }] : []),
    ...(can(effectiveUser, "trash_view") ? [{ id: "kos", label: "Kôš" }] : []),
    ...(isAdminUser(effectiveUser) ? [{ id: "audit", label: "Audit log" }] : []),
  ];
  // Externý šofér nemá vidieť nič okrem svojich preprav.
  return [
    {
      id: "poziciovna",
      label: "Požičovňa",
      tabs: effectiveUser?.role === "externy_sofer" ? poziciovnaTabs.filter((t) => t.id === "prepravy") : poziciovnaTabs,
      badge: 0,
    },
    ...(effectiveUser?.role !== "externy_sofer" ? [{ id: "servis", label: "Servis", tabs: servisTabs, badge: damageAlertCount }] : []),
    ...(can(effectiveUser, "employee_manage") ? [{ id: "administrativa", label: "Administratíva", tabs: administrativaTabs, badge: 0 }] : []),
  ];
}

// Bočné menu (text) — používa sa len vnútri výsuvnej zásuvky na mobile (viď
// <Header>). Na webe ho nahradil IconRail nižšie. "otvorený" modul je vždy
// presne ten aktívny (module === m.id), žiadny samostatný stav navyše. Klik
// na iný modul prepne naň (setModule si už aj predtým vyberal jeho prvú
// záložku), klik na záložku v OTVORENOM module len prepne pohľad.
function SidebarNav({ module, view, effectiveUser, damageAlertCount, onSelectModule, onSelectView, onPickDocumentsSubView, quickActionsByModule, className, docsExpanded: docsExpandedProp, onToggleDocsExpanded }) {
  const [docsExpandedState, setDocsExpandedState] = useState(false);
  // V mobilnej zásuvke si tento stav drží sama (nikto ho nekontroluje zvonku).
  // V IconRail flyoute ho kontroluje IconRail (onToggleDocsExpanded je daný),
  // lebo aj pás potrebuje vedieť, či sú podzáložky Dokumentov rozbalené, nech
  // pridá/uberie im zodpovedajúce bodky.
  const docsExpanded = onToggleDocsExpanded ? docsExpandedProp : docsExpandedState;
  const toggleDocsExpanded = onToggleDocsExpanded || (() => setDocsExpandedState((v) => !v));
  const modules = buildNavModules(effectiveUser, damageAlertCount);
  // Moduly (Požičovňa/Servis/Administratíva) sú zoskupené hore ako jeden
  // blok, oddelené jednou čiarou od záložiek AKTUÁLNE otvoreného modulu pod
  // nimi — namiesto pôvodného akordeónu (záložky priamo pod svojím modulom,
  // ostatné moduly sa posúvali). IconRail nižšie musí mať rovnaké poradie
  // riadkov 1:1 (viď railRows tam).
  const activeModule = modules.find((m) => m.id === module);
  const quickActions = quickActionsByModule?.[module];

  return (
    <nav className={className || "sidebar-nav"}>
      <div className="sidebar-modules">
        {modules.map((m) => (
          <button key={m.id} className={`sidebar-group${module === m.id ? " active" : ""}`} onClick={() => onSelectModule(m.id)}>
            <span>{m.label}</span>
            {m.badge > 0 && <span className="sidebar-badge">{m.badge}</span>}
          </button>
        ))}
      </div>
      {activeModule && (
        <div className="sidebar-tabs">
          {activeModule.tabs.map((t) =>
            t.dropdown ? (
              <div key={t.id}>
                <button className="sidebar-item" onClick={toggleDocsExpanded}>
                  {t.label} {docsExpanded ? "▴" : "▾"}
                </button>
                {docsExpanded &&
                  ((DOCUMENT_SUBTABS[activeModule.id] || []).length === 0 ? (
                    <div className="sidebar-subnote">Táto sekcia sa pripravuje.</div>
                  ) : (
                    (DOCUMENT_SUBTABS[activeModule.id] || []).map((st) => (
                      <button
                        key={st.id}
                        className="sidebar-item sidebar-subitem"
                        onClick={() => {
                          onSelectModule(activeModule.id);
                          onPickDocumentsSubView(st);
                        }}
                      >
                        {st.label}
                        {st.url && <span style={{ marginLeft: "auto", fontSize: 11 }}>↗</span>}
                      </button>
                    ))
                  ))}
              </div>
            ) : (
              <button
                key={t.id}
                className={`sidebar-item${view === t.id ? " active" : ""}`}
                onClick={() => {
                  onSelectModule(activeModule.id);
                  onSelectView(t.id);
                }}
              >
                {t.label}
                {t.id === "poskodenia" && activeModule.badge > 0 && <span className="sidebar-badge" style={{ marginLeft: "auto" }}>{activeModule.badge}</span>}
              </button>
            )
          )}
          {quickActions?.length > 0 && (
            <div className="sidebar-quick">
              {quickActions.map((qa) =>
                qa.href ? (
                  <a key={qa.key} className="sidebar-item quick" href={qa.href} target="_blank" rel="noopener noreferrer">
                    {qa.label}
                  </a>
                ) : (
                  <button key={qa.key} className="sidebar-item quick" onClick={qa.onClick}>
                    {qa.label}
                  </button>
                )
              )}
            </div>
          )}
        </div>
      )}
    </nav>
  );
}

