// Excel-štýl filter — zoznam hodnôt so zaškrtávacími políčkami, predvolene
// všetko zaškrtnuté (nič sa neschová, kým si niekto sám nezúži výber).
function ColumnFilterButton({ label, options, selected, onChange }) {
  const [open, setOpen] = useState(false);
  const allSelected = options.every((o) => selected.has(o));
  return (
    <span style={{ position: "relative", display: "inline-block", marginLeft: 4 }}>
      <button
        className="btn btn-ghost"
        style={{ padding: "1px 5px", fontSize: 10, opacity: allSelected ? 0.5 : 1 }}
        onClick={(e) => { e.stopPropagation(); setOpen((v) => !v); }}
        title={`Filter: ${label}`}
      >
        ▾
      </button>
      {open && (
        <div
          style={{
            position: "absolute", top: "100%", left: 0, marginTop: 2, zIndex: 30,
            background: "var(--panel)", border: "1px solid var(--border)", borderRadius: 8,
            boxShadow: "0 4px 16px rgba(0,0,0,.10)", minWidth: 180, maxHeight: 260, overflowY: "auto", padding: 6,
          }}
        >
          <div style={{ display: "flex", gap: 6, marginBottom: 6, fontSize: 11 }}>
            <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px" }} onClick={() => onChange(new Set(options))}>Vybrať všetko</button>
            <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px" }} onClick={() => onChange(new Set())}>Zrušiť všetko</button>
          </div>
          {options.map((o) => (
            <label key={o} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, padding: "3px 4px", cursor: "pointer" }}>
              <input
                type="checkbox"
                checked={selected.has(o)}
                onChange={(e) => {
                  const next = new Set(selected);
                  if (e.target.checked) next.add(o); else next.delete(o);
                  onChange(next);
                }}
              />
              {o || "— bez hodnoty —"}
            </label>
          ))}
        </div>
      )}
    </span>
  );
}

function urcenieLabel(u) {
  if (!u || !u.typ) return "—";
  if (u.typ === "sklad") return "Na sklad";
  if (u.typ === "externa") return u.externaText ? `Externá zákazka: ${u.externaText}` : "Externá zákazka";
  if (u.typ === "stroj") return u.strojKod || "Stroj";
  return "—";
}

function copyColumn(rows, key, label) {
  const text = rows.map((r) => r[key] || "").join("\n");
  navigator.clipboard.writeText(text).then(
    () => {},
    () => alert(`Kopírovanie zlyhalo — skopíruj stĺpec "${label}" ručne.`)
  );
}

function exportSparePartsCSV(rows, filename) {
  const data = rows.map((p) => ({
    Depo: p.depo || "",
    Určenie: p.urcenie !== undefined ? urcenieLabel(p.urcenie) : "",
    Dodávateľ: p.dodavatel || "",
    "Číslo položky": p.cisloPolozky || "",
    "Počet kusov": p.pocetKusov || "",
    "Číslo dielu": p.cisloDielu || "",
    "Popis dielu": p.popisDielu || "",
    "Stav objednania": p.stav || "",
    "Dátum objednania": p.datumObjednania ? fmtDate(p.datumObjednania) : "",
    "Nákupná objednávka": p.nakupnaObjednavka || "",
    Poznámka: p.poznamka || "",
    "Zadal(a)": p.requestedBy || "",
  }));
  const csv = Papa.unparse(data);
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" }); // BOM, nech Excel nezobrazí diakritiku zle
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function SparePartsView({ spareParts, machines, myEmployee, user, today, targetDepo, onTargetDepoConsumed, onAdd, onApprove, onReject, onRestore, onUpdate, onDelete, onImport }) {
  const canManage = can(user, "sparepart_manage");
  const myDepo = myEmployee?.depo || "";
  // "Vedúci technik" role vidí/objednáva len na svoje depá (napr. BA + NR),
  // ostatní s právom sparepart_manage (dispečer/vedúci servisu) na všetky.
  const allowedDepos = myAssignableDepos(user);
  const depoOptions = allowedDepos || DEPO_OPTIONS.filter((d) => d !== "Externé");
  const [activeDepo, setActiveDepo] = useState(canManage ? depoOptions[0] : myDepo);
  const [dodavatelFilter, setDodavatelFilter] = useState(null); // null = všetko zaškrtnuté (predvolené)
  const [periodMode, setPeriodMode] = useState("month"); // month | all | custom
  const [customStart, setCustomStart] = useState(today.slice(0, 8) + "01");
  const [customEnd, setCustomEnd] = useState(today);
  const [showAdd, setShowAdd] = useState(false);
  const [rejectingId, setRejectingId] = useState(null);
  const [uncheckedPendingIds, setUncheckedPendingIds] = useState(() => new Set()); // pri hromadnom schválení — odškrtnuté id sa vynechajú
  const [confirmMessage, setConfirmMessage] = useState(null); // krátky zatvárateľný pás po odoslaní požiadavky
  const [searchQuery, setSearchQuery] = useState(""); // vyhľadávanie histórie naprieč všetkými depami a celým časom

  // Prišli sme sem kliknutím na notifikáciu o konkrétnom diele — prepneme
  // rovno na jeho depo, nech ho vedúci/dispečer nemusí ručne hľadať.
  useEffect(() => {
    if (targetDepo && canManage) {
      setActiveDepo(targetDepo);
      setDodavatelFilter(null);
      onTargetDepoConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [targetDepo]);

  const depo = canManage ? activeDepo : myDepo;
  const { start, end } = periodBounds(periodMode, today, customStart, customEnd);

  const depoRows = spareParts.filter((p) => p.depo === depo);
  // Filter obdobia sa týka LEN už objednaných položiek — nevybavené sa majú
  // vidieť vždy, nech sa nestratia z dohľadu len preto, že prešiel mesiac.
  const periodFiltered = periodMode === "all"
    ? depoRows
    : depoRows.filter((p) => p.stav !== SPAREPART_STAV.OBJEDNANE || !p.datumObjednania || (p.datumObjednania >= start && p.datumObjednania <= end));

  const dodavatelOptions = [...new Set(periodFiltered.map((p) => p.dodavatel || ""))].sort();
  const selectedDodavatelia = dodavatelFilter || new Set(dodavatelOptions);
  const rows = periodFiltered.filter((p) => selectedDodavatelia.has(p.dodavatel || ""));

  const pending = rows.filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_SCHVALENIE);
  const zamietnute = rows.filter((p) => p.stav === SPAREPART_STAV.ZAMIETNUTE);
  // Objednané hore, zoradené podľa čísla nákupnej objednávky (od najmenšieho).
  const objednane = rows
    .filter((p) => p.stav === SPAREPART_STAV.OBJEDNANE)
    .sort((a, b) => (a.nakupnaObjednavka || "").localeCompare(b.nakupnaObjednavka || "", undefined, { numeric: true }));
  // Čaká na objednanie pod tým, zoradené podľa dodávateľa — nech sa dá kopírovať
  // dodávateľ po dodávateľovi bez miešania s už objednanými vecami.
  const cakaNaObjednanie = rows
    .filter((p) => p.stav === SPAREPART_STAV.CAKA_NA_OBJEDNANIE)
    .sort((a, b) => (a.dodavatel || "").localeCompare(b.dodavatel || ""));

  const columns = [
    { key: "dodavatel", label: "Dodávateľ" },
    { key: "cisloPolozky", label: "Číslo položky" },
    { key: "pocetKusov", label: "Počet kusov" },
    { key: "cisloDielu", label: "Číslo dielu" },
    { key: "popisDielu", label: "Popis dielu" },
    { key: "poznamka", label: "Poznámka" },
  ];

  // Vyhľadávanie histórie — naprieč VŠETKÝMI depami (u technika len jeho
  // vlastné) a CELÝM časom, nezávisle od filtra obdobia a aktívnej záložky.
  const searchScope = canManage ? spareParts : spareParts.filter((p) => p.depo === myDepo);
  const q = searchQuery.trim().toLowerCase();
  const searchResults = q
    ? searchScope
        .filter((p) => (p.cisloDielu || "").toLowerCase().includes(q) || (p.popisDielu || "").toLowerCase().includes(q))
        .sort((a, b) => (b.requestedAt || "").localeCompare(a.requestedAt || ""))
    : [];

  function renderGroupTable(groupRows, groupLabel, groupColor, showDodavatelFilter) {
    return (
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: groupColor }}>
            {groupLabel} ({groupRows.length})
          </div>
          {groupRows.length > 0 && (
            <button
              className="btn btn-ghost"
              style={{ fontSize: 10, padding: "2px 8px" }}
              onClick={() => exportSparePartsCSV(groupRows, `nahradne-diely-${depo}-${groupLabel.toLowerCase().replace(/\s+/g, "-")}.csv`)}
            >
              ⬇ Export do Excelu
            </button>
          )}
        </div>
        <div className="panel" style={{ padding: 0, overflow: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                {columns.map((c) => (
                  <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)", whiteSpace: "nowrap" }}>
                    {c.label}
                    {c.key === "dodavatel" && showDodavatelFilter && (
                      <ColumnFilterButton label="Dodávateľ" options={dodavatelOptions} selected={selectedDodavatelia} onChange={setDodavatelFilter} />
                    )}
                    {" "}
                    <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title={`Kopírovať stĺpec ${c.label}`} onClick={() => copyColumn(groupRows, c.key, c.label)}>⧉</button>
                  </th>
                ))}
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>
                  Určenie {" "}
                  <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title="Kopírovať stĺpec Určenie" onClick={() => copyColumn(groupRows.map((p) => ({ urcenieText: urcenieLabel(p.urcenie) })), "urcenieText", "Určenie")}>⧉</button>
                </th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Stav objednania</th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dátum objednania</th>
                <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>
                  Nákupná objednávka {" "}
                  <button className="btn btn-ghost" style={{ padding: "1px 5px", fontSize: 10 }} title="Kopírovať stĺpec Nákupná objednávka" onClick={() => copyColumn(groupRows, "nakupnaObjednavka", "Nákupná objednávka")}>⧉</button>
                </th>
                {canManage && <th></th>}
              </tr>
            </thead>
            <tbody>
              {groupRows.length === 0 ? (
                <tr><td colSpan={11} style={{ padding: 16, fontSize: 13, color: "var(--text-dim)" }}>Žiadne položky nezodpovedajú filtru.</td></tr>
              ) : (
                groupRows.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {columns.map((c) =>
                      canManage ? (
                        <td key={c.key} style={{ padding: "4px 12px" }}>
                          <input
                            type={c.key === "pocetKusov" ? "number" : "text"}
                            value={p[c.key] || ""}
                            onChange={(e) => onUpdate(p.id, { [c.key]: e.target.value })}
                            style={{ fontSize: 13, width: c.key === "popisDielu" ? 160 : c.key === "pocetKusov" ? 60 : 100 }}
                          />
                        </td>
                      ) : (
                        <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>
                      )
                    )}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <select
                          value={p.stav}
                          onChange={(e) => {
                            const newStav = e.target.value;
                            onUpdate(p.id, newStav === SPAREPART_STAV.OBJEDNANE ? { stav: newStav, datumObjednania: today } : { stav: newStav });
                          }}
                          style={{
                            fontSize: 12, fontWeight: 600, border: "none", borderRadius: 5, padding: "3px 8px",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : "var(--warn)",
                            color: "#fff",
                          }}
                        >
                          <option value={SPAREPART_STAV.CAKA_NA_OBJEDNANIE}>Čaká na objednanie</option>
                          <option value={SPAREPART_STAV.OBJEDNANE}>Objednané</option>
                        </select>
                      ) : (
                        <span
                          style={{
                            fontSize: 12, fontWeight: 600, borderRadius: 5, padding: "3px 8px", color: "#fff",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : "var(--warn)",
                          }}
                        >
                          {p.stav}
                        </span>
                      )}
                    </td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <input type="date" value={p.datumObjednania || ""} onChange={(e) => onUpdate(p.id, { datumObjednania: e.target.value })} style={{ fontSize: 12 }} />
                      ) : (
                        <span style={{ fontSize: 13 }}>{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</span>
                      )}
                    </td>
                    <td style={{ padding: "6px 12px" }}>
                      {canManage ? (
                        <input value={p.nakupnaObjednavka || ""} onChange={(e) => onUpdate(p.id, { nakupnaObjednavka: e.target.value })} style={{ fontSize: 12, width: 110 }} />
                      ) : (
                        <span style={{ fontSize: 13 }}>{p.nakupnaObjednavka || "—"}</span>
                      )}
                    </td>
                    {canManage && (
                      <td style={{ padding: "6px 12px" }}>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px", color: "var(--danger)" }} title="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10, marginBottom: 14 }}>
        {canManage ? (
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            {depoOptions.map((d) => (
              <button
                key={d}
                className="btn"
                onClick={() => { setActiveDepo(d); setDodavatelFilter(null); }}
                style={{
                  fontSize: 12, padding: "5px 12px",
                  background: activeDepo === d ? "var(--accent)" : "transparent",
                  color: activeDepo === d ? "#fff" : "var(--text)",
                  border: "1px solid " + (activeDepo === d ? "var(--accent)" : "var(--border)"),
                }}
              >
                {d}
              </button>
            ))}
          </div>
        ) : (
          <div style={{ fontSize: 13, fontWeight: 600 }}>Depo: {myDepo || "— nemáte priradené depo —"}</div>
        )}
        <button className="btn btn-accent" onClick={() => setShowAdd(true)}>+ Nová požiadavka</button>
      </div>

      {confirmMessage && (
        <div
          style={{
            display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
            background: "var(--ok)", color: "#fff", padding: "10px 14px", borderRadius: 8, marginBottom: 16, fontSize: 13,
          }}
        >
          <span>✓ {confirmMessage}</span>
          <button className="btn btn-ghost" style={{ color: "#fff", padding: "2px 8px" }} onClick={() => setConfirmMessage(null)}>✕</button>
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
        <input
          type="text"
          placeholder="Hľadať v histórii podľa čísla alebo popisu dielu (naprieč všetkými depami a celým časom)..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ flex: 1, maxWidth: 480 }}
        />
        {q && <button className="btn btn-ghost" onClick={() => setSearchQuery("")}>✕ Zrušiť hľadanie</button>}
      </div>

      {q ? (
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)" }}>
              Výsledky hľadania ({searchResults.length})
            </div>
            {searchResults.length > 0 && (
              <button className="btn btn-ghost" style={{ fontSize: 10, padding: "2px 8px" }} onClick={() => exportSparePartsCSV(searchResults, `nahradne-diely-hladanie-${q}.csv`)}>
                ⬇ Export do Excelu
              </button>
            )}
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Depo</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Stav</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dátum objednania</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Nákupná objednávka</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dodávateľ</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Počet kusov</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Číslo dielu</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Popis dielu</th>
                </tr>
              </thead>
              <tbody>
                {searchResults.length === 0 ? (
                  <tr><td colSpan={9} style={{ padding: 16, fontSize: 13, color: "var(--text-dim)" }}>Nič sa nenašlo.</td></tr>
                ) : (
                  searchResults.map((p) => (
                    <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.depo}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                      <td style={{ padding: "6px 12px" }}>
                        <span
                          style={{
                            fontSize: 12, fontWeight: 600, borderRadius: 5, padding: "3px 8px", color: "#fff",
                            background: p.stav === SPAREPART_STAV.OBJEDNANE ? "var(--ok)" : p.stav === SPAREPART_STAV.ZAMIETNUTE ? "var(--danger)" : "var(--warn)",
                          }}
                        >
                          {p.stav}
                        </span>
                      </td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.datumObjednania ? fmtDate(p.datumObjednania) : "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.nakupnaObjednavka || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.dodavatel || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.pocetKusov || "—"}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.cisloDielu}</td>
                      <td style={{ padding: "6px 12px", fontSize: 13 }}>{p.popisDielu}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
      <>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
        {[["month", "Objednané: tento mesiac"], ["all", "Objednané: všetko"], ["custom", "Vlastný rozsah"]].map(([id, label]) => (
          <button
            key={id}
            className="btn"
            onClick={() => setPeriodMode(id)}
            style={{
              fontSize: 12, padding: "4px 10px",
              background: periodMode === id ? "var(--accent)" : "transparent",
              color: periodMode === id ? "#fff" : "var(--text-dim)",
              border: "1px solid " + (periodMode === id ? "var(--accent)" : "var(--border)"),
            }}
          >
            {label}
          </button>
        ))}
        {periodMode === "custom" && (
          <>
            <input type="date" value={customStart} onChange={(e) => setCustomStart(e.target.value)} />
            <span style={{ color: "var(--text-dim)" }}>—</span>
            <input type="date" value={customEnd} onChange={(e) => setCustomEnd(e.target.value)} />
          </>
        )}
      </div>

      {pending.length > 0 && canManage && (
        <div style={{ marginBottom: 20 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8, flexWrap: "wrap" }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--warn)" }}>
              Čaká na schválenie ({pending.length})
            </div>
            {pending.length > 1 && (
              <button
                className="btn btn-accent"
                style={{ fontSize: 11, padding: "3px 8px" }}
                onClick={() => {
                  pending.filter((p) => !uncheckedPendingIds.has(p.id)).forEach((p) => onApprove(p.id));
                  setUncheckedPendingIds(new Set());
                }}
              >
                Schváliť vybrané ({pending.filter((p) => !uncheckedPendingIds.has(p.id)).length})
              </button>
            )}
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {pending.length > 1 && <th></th>}
                  {columns.map((c) => <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>{c.label}</th>)}
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {pending.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {pending.length > 1 && (
                      <td style={{ padding: "6px 12px" }}>
                        <input
                          type="checkbox"
                          checked={!uncheckedPendingIds.has(p.id)}
                          onChange={(e) =>
                            setUncheckedPendingIds((prev) => {
                              const next = new Set(prev);
                              if (e.target.checked) next.delete(p.id); else next.add(p.id);
                              return next;
                            })
                          }
                        />
                      </td>
                    )}
                    {columns.map((c) => <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>)}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px", display: "flex", gap: 6 }}>
                      <button className="btn btn-accent" style={{ fontSize: 11, padding: "3px 8px" }} onClick={() => onApprove(p.id)}>Schváliť</button>
                      <button className="btn btn-ghost" style={{ fontSize: 11, padding: "3px 8px", color: "var(--danger)" }} onClick={() => setRejectingId(p.id)}>Zamietnuť</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {renderGroupTable(objednane, "Objednané", "var(--ok)", false)}
      {renderGroupTable(cakaNaObjednanie, "Čaká na objednanie", "var(--warn)", true)}
      {zamietnute.length > 0 && (
        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--danger)", marginBottom: 8 }}>
            Zamietnuté ({zamietnute.length})
          </div>
          <div className="panel" style={{ padding: 0, overflow: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  {columns.map((c) => <th key={c.key} style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>{c.label}</th>)}
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Určenie</th>
                  <th style={{ textAlign: "left", padding: "8px 12px", fontSize: 11, color: "var(--text-dim)" }}>Dôvod</th>
                  {canManage && <th></th>}
                </tr>
              </thead>
              <tbody>
                {zamietnute.map((p) => (
                  <tr key={p.id} style={{ borderTop: "1px solid var(--border)" }}>
                    {columns.map((c) => <td key={c.key} style={{ padding: "6px 12px", fontSize: 13 }}>{p[c.key] || "—"}</td>)}
                    <td style={{ padding: "6px 12px", fontSize: 13, whiteSpace: "nowrap" }}>{urcenieLabel(p.urcenie)}</td>
                    <td style={{ padding: "6px 12px", fontSize: 13, color: "var(--danger)" }}>{p.rejectionReason}</td>
                    {canManage && (
                      <td style={{ padding: "6px 12px", display: "flex", gap: 6 }}>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 8px" }} onClick={() => onRestore(p.id)}>Obnoviť</button>
                        <button className="btn btn-ghost" style={{ fontSize: 11, padding: "2px 6px", color: "var(--danger)" }} title="Vymazať riadok" onClick={() => onDelete(p.id)}>🗑</button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {canManage && (
        <div style={{ marginTop: 14 }}>
          <SparePartsImportButton depo={depo} onImport={onImport} />
        </div>
      )}
      </>
      )}

      {showAdd && (
        <AddSparePartModal
          canManage={canManage}
          defaultDepo={depo}
          depoOptions={depoOptions}
          machines={machines}
          onClose={() => setShowAdd(false)}
          onSave={(data) => {
            onAdd(data);
            setShowAdd(false);
            if (!canManage) {
              setConfirmMessage(
                data.length === 1
                  ? `Požiadavka odoslaná na schválenie: ${data[0].pocetKusov}× ${data[0].cisloDielu} — ${data[0].popisDielu}`
                  : `Požiadavka odoslaná na schválenie: ${data.length} položiek`
              );
            }
          }}
        />
      )}
      {rejectingId && (
        <RejectSparePartModal
          onClose={() => setRejectingId(null)}
          onConfirm={(reason) => { onReject(rejectingId, reason); setRejectingId(null); }}
        />
      )}
    </div>
  );
}

function SparePartsImportButton({ depo, onImport }) {
  const [show, setShow] = useState(false);
  const [rows, setRows] = useState([]);
  const [headers, setHeaders] = useState([]);
  const [mapDodavatel, setMapDodavatel] = useState("");
  const [mapCisloPolozky, setMapCisloPolozky] = useState("");
  const [mapPocetKusov, setMapPocetKusov] = useState("");
  const [mapCisloDielu, setMapCisloDielu] = useState("");
  const [mapPopisDielu, setMapPopisDielu] = useState("");
  const [mapStav, setMapStav] = useState("");
  const [mapDatum, setMapDatum] = useState("");
  const [mapObjednavka, setMapObjednavka] = useState("");
  const [mapPoznamka, setMapPoznamka] = useState("");

  function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (res) => {
        setHeaders(res.meta.fields || []);
        setRows(res.data);
      },
    });
  }

  function doImport() {
    const items = rows
      .map((r) => ({
        depo,
        dodavatel: mapDodavatel ? (r[mapDodavatel] || "").toString().trim() : "",
        cisloPolozky: mapCisloPolozky ? (r[mapCisloPolozky] || "").toString().trim() : "",
        pocetKusov: mapPocetKusov ? (r[mapPocetKusov] || "").toString().trim() : "",
        cisloDielu: mapCisloDielu ? (r[mapCisloDielu] || "").toString().trim() : "",
        popisDielu: mapPopisDielu ? (r[mapPopisDielu] || "").toString().trim() : "",
        stav: mapStav && (r[mapStav] || "").toString().trim() ? (r[mapStav] || "").toString().trim() : SPAREPART_STAV.OBJEDNANE,
        datumObjednania: mapDatum ? (r[mapDatum] || "").toString().trim() : "",
        nakupnaObjednavka: mapObjednavka ? (r[mapObjednavka] || "").toString().trim() : "",
        poznamka: mapPoznamka ? (r[mapPoznamka] || "").toString().trim() : "",
      }))
      .filter((x) => x.cisloDielu);
    onImport(items);
    setShow(false);
    setRows([]);
    setHeaders([]);
  }

  return (
    <>
      <button className="btn btn-ghost" onClick={() => setShow(true)}>Importovať históriu z Excelu (pre {depo})</button>
      {show && (
        <Modal title={`Import histórie náhradných dielov — ${depo}`} onClose={() => setShow(false)} wide>
          <Field label="Vyberte CSV súbor (exportovaný z Excelu, len pre toto depo)">
            <input type="file" accept=".csv" onChange={handleFile} />
          </Field>
          {headers.length > 0 && (
            <>
              <div className="resp-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 14 }}>
                {[
                  ["Dodávateľ", mapDodavatel, setMapDodavatel],
                  ["Číslo položky", mapCisloPolozky, setMapCisloPolozky],
                  ["Počet kusov", mapPocetKusov, setMapPocetKusov],
                  ["Číslo dielu", mapCisloDielu, setMapCisloDielu],
                  ["Popis dielu", mapPopisDielu, setMapPopisDielu],
                  ["Stav objednania", mapStav, setMapStav],
                  ["Dátum objednania", mapDatum, setMapDatum],
                  ["Nákupná objednávka", mapObjednavka, setMapObjednavka],
                  ["Poznámka", mapPoznamka, setMapPoznamka],
                ].map(([label, val, setter]) => (
                  <Field key={label} label={`Stĺpec = ${label}`}>
                    <select value={val} onChange={(e) => setter(e.target.value)} style={{ width: "100%" }}>
                      <option value="">—</option>
                      {headers.map((h) => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </Field>
                ))}
              </div>
              <button className="btn btn-accent" disabled={!mapCisloDielu} onClick={doImport}>Importovať {rows.length} riadkov do {depo}</button>
            </>
          )}
        </Modal>
      )}
    </>
  );
}

function DepoCheckerSettingsView({ depoCheckers, technicians, checkerSubstitutions, onDeleteSubstitution, onSave }) {
  const [values, setValues] = useState(depoCheckers || {});
  const technicianName = (id) => technicians.find((t) => t.id === id)?.name || "—";

  return (
    <div>
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 16 }}>
        Kto skontroluje/pripraví stroj na danom depe pri vývoze aj zvoze — platforma to už nebude pýtať pri
        každej zákazke zvlášť. Zmeňte tu kedykoľvek (dovolenka, zmena osoby na tejto úlohe a pod.) —
        pri zadaní dovolenky checkerovi priamo v Pláne servisu platforma navyše sama ponúkne dočasnú náhradu.
      </div>
      <div style={{ maxWidth: 420 }}>
        {DEPO_OPTIONS.map((depo) => (
          <Field key={depo} label={depo}>
            <select
              value={values[depo] || ""}
              onChange={(e) => setValues((v) => ({ ...v, [depo]: e.target.value || undefined }))}
              style={{ width: "100%" }}
            >
              <option value="">— nenastavené —</option>
              {technicians.filter((t) => !t.archived).map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </Field>
        ))}
        <button
          className="btn btn-accent"
          style={{ marginBottom: 20 }}
          onClick={() => {
            // vyčistí prázdne hodnoty, nech sa v databáze nehromadí "undefined"
            const cleaned = {};
            Object.entries(values).forEach(([k, v]) => {
              if (v) cleaned[k] = v;
            });
            onSave(cleaned);
          }}
        >
          Uložiť
        </button>
      </div>
      {checkerSubstitutions && checkerSubstitutions.length > 0 && (
        <>
          <div style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".06em", color: "var(--text-dim)", marginBottom: 8 }}>
            Aktívne/naplánované náhrady (dovolenka)
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxWidth: 560 }}>
            {checkerSubstitutions.map((s) => (
              <div key={s.id} className="panel" style={{ padding: 10, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", fontSize: 12 }}>
                <span><strong>{s.depo}</strong>: {technicianName(s.originalTechnicianId)} → {technicianName(s.substituteTechnicianId)}</span>
                <span style={{ color: "var(--text-dim)" }}>({fmtDate(s.startDate)} – {fmtDate(s.endDate)})</span>
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 11, padding: "3px 7px", color: "var(--danger)", marginLeft: "auto" }}
                  onClick={() => onDeleteSubstitution(s.id)}
                >
                  Zmazať
                </button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// Audit log (13.3) — kto čo zmenil/zmazal. Dáta sa neťahajú pri štarte appky ako
// ostatné (bolo by to zbytočné pre 99% otvorení appky) — načíta sa až pri otvorení
// tejto záložky. Prístup majú len administrátori (rovnako obmedzené aj v RLS).
const AUDIT_TABLE_LABELS = {
  damages: "Poškodenia / servis",
  jobs: "Zákazky (požičovňa)",
  machines: "Stroje",
  spareParts: "Náhradné diely",
};
const AUDIT_ACTION_LABELS = { insert: "Vytvorené", update: "Upravené", delete: "Zmazané" };
function AuditLogView({ profiles }) {
  const [entries, setEntries] = useState(null); // null = ešte sa načítava
  const [tableFilter, setTableFilter] = useState("");
  const [error, setError] = useState(null);
  const profileById = useMemo(() => Object.fromEntries(profiles.map((p) => [p.id, p])), [profiles]);

  useEffect(() => {
    let cancelled = false;
    supabase
      .from("audit_log")
      .select("*")
      .order("changed_at", { ascending: false })
      .limit(300)
      .then(({ data, error: err }) => {
        if (cancelled) return;
        if (err) {
          console.error("Načítanie audit logu zlyhalo", err);
          setError(err.message || "Neznáma chyba");
          return;
        }
        setEntries(data || []);
      });
    return () => { cancelled = true; };
  }, []);

  const filtered = tableFilter ? (entries || []).filter((e) => e.table_name === tableFilter) : entries || [];

  return (
    <div>
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 14 }}>
        Posledných {entries?.length || 0} zmien v citlivých tabuľkách (poškodenia/servis, zákazky, stroje, náhradné
        diely) — zaznamenáva sa priamo v databáze, nedá sa obísť z appky.
      </div>
      <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
        <button
          className="btn"
          onClick={() => setTableFilter("")}
          style={{ padding: "5px 10px", fontSize: 11, background: !tableFilter ? "var(--accent)" : "transparent", color: !tableFilter ? "#fff" : "var(--text-dim)", border: "1px solid " + (!tableFilter ? "var(--accent)" : "var(--border)") }}
        >
          Všetko
        </button>
        {Object.entries(AUDIT_TABLE_LABELS).map(([t, label]) => (
          <button
            key={t}
            className="btn"
            onClick={() => setTableFilter(tableFilter === t ? "" : t)}
            style={{ padding: "5px 10px", fontSize: 11, background: tableFilter === t ? "var(--accent)" : "transparent", color: tableFilter === t ? "#fff" : "var(--text-dim)", border: "1px solid " + (tableFilter === t ? "var(--accent)" : "var(--border)") }}
          >
            {label}
          </button>
        ))}
      </div>
      {error && (
        <div className="panel" style={{ padding: 20, color: "var(--danger)" }}>
          Nepodarilo sa načítať audit log: {error}
        </div>
      )}
      {!error && entries === null && (
        <div className="panel" style={{ padding: 30, textAlign: "center", color: "var(--text-dim)" }}>Načítavam…</div>
      )}
      {!error && entries !== null && (
        <div className="panel">
          <table>
            <thead>
              <tr>
                <th>Kedy</th>
                <th>Kto</th>
                <th>Tabuľka</th>
                <th>Akcia</th>
                <th>Záznam</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 && (
                <tr><td colSpan={5} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Žiadne zmeny v tomto filtri.</td></tr>
              )}
              {filtered.map((e) => {
                const who = e.changed_by ? profileById[e.changed_by]?.name || "— neznámy účet —" : "— systém —";
                const data = e.action === "delete" ? e.old_data : e.new_data;
                const label = data?.code || data?.name || data?.customer || e.record_id;
                return (
                  <tr key={e.id}>
                    <td style={{ fontSize: 12, whiteSpace: "nowrap" }}>{new Date(e.changed_at).toLocaleString("sk-SK")}</td>
                    <td>{who}</td>
                    <td>{AUDIT_TABLE_LABELS[e.table_name] || e.table_name}</td>
                    <td>
                      <span className={`badge ${e.action === "delete" ? "badge-danger" : e.action === "insert" ? "badge-ok" : "badge-info"}`}>
                        {AUDIT_ACTION_LABELS[e.action] || e.action}
                      </span>
                    </td>
                    <td className="mono" style={{ fontSize: 12 }}>{label}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function UserAdminModal({ profiles, currentUser, onClose, onUpdate, onDelete, onResetPassword }) {
  const [editingId, setEditingId] = useState(null);

  return (
    <Modal title="Správa používateľov" onClose={onClose} wide>
      <div style={{ fontSize: 13, color: "var(--text-dim)", marginBottom: 14 }}>
        Noví ľudia sa registrujú sami na prihlasovacej obrazovke — tu im len prideľte rolu, prípadne ich deaktivujte/zmažte.
      </div>
      <table className="table-cards">
        <thead>
          <tr>
            <th>Meno</th>
            <th>Email</th>
            <th>Rola</th>
            <th>Stav</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {profiles.length === 0 && (
            <tr><td className="td-plain" colSpan={5} style={{ textAlign: "center", padding: 30, color: "var(--text-dim)" }}>Zatiaľ žiadni používatelia.</td></tr>
          )}
          {profiles.map((p) => (
            <tr key={p.id}>
              <td className="td-plain" style={{ fontWeight: 600 }}>{p.name}{p.id === currentUser?.id ? " (vy)" : ""}</td>
              <td className="mono" data-label="Email">{p.email || (p.id === currentUser?.id ? currentUser.email : "—")}</td>
              <td data-label="Rola">
                {p.id === currentUser?.id ? (
                  <span
                    style={{ color: "var(--text-dim)" }}
                    title="Svoju vlastnú rolu si nemôžete zmeniť — musí ju zmeniť iný administrátor (poistka, aby platforma neostala bez admina)"
                  >
                    {roleLabel(p.role)}
                  </span>
                ) : editingId === p.id ? (
                  <select
                    autoFocus
                    defaultValue={p.role}
                    onChange={(e) => { onUpdate(p.id, { role: e.target.value }); setEditingId(null); }}
                    onBlur={() => setEditingId(null)}
                  >
                    {ROLES.map((r) => <option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                ) : (
                  <span style={{ cursor: "pointer", textDecoration: "underline" }} onClick={() => setEditingId(p.id)}>
                    {roleLabel(p.role)}
                  </span>
                )}
              </td>
              <td data-label="Stav">{p.active === false ? <span className="badge badge-danger">Deaktivovaný</span> : <span className="badge badge-ok">Aktívny</span>}</td>
              <td className="td-actions" style={{ textAlign: "right" }}>
                <KebabMenu
                  actions={[
                    (p.email || p.id === currentUser?.id) && { label: "Resetovať heslo", onClick: () => onResetPassword(p.email || currentUser.email) },
                    p.id !== currentUser?.id && { label: p.active === false ? "Aktivovať" : "Deaktivovať", onClick: () => onUpdate(p.id, { active: p.active === false ? true : false }) },
                    p.id !== currentUser?.id && { label: "Zmazať", onClick: () => onDelete(p.id), danger: true },
                  ]}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </Modal>
  );
}

function GlobalStyle() {
  return (
    <style>{`
      *, *::before, *::after { box-sizing: border-box; }
      @import url('https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600;700&family=Barlow+Condensed:wght@600;700&display=swap');
      :root {
        --bg: #f0f0f0;
        --panel: #ffffff;
        --panel-2: #f4f4f4;
        --border: #e0e0e0;
        --text: #1a1a1a;
        --text-dim: #6b6b6b;
        --accent: #E30613;
        --accent-dark: #B5040F;
        --accent-light: #fdf0f0;
        --ok: #3b6d11;
        --ok-bg: #eaf3de;
        --warn: #854f0b;
        --warn-bg: #faeeda;
        --gantt-name-col: 150px;
        --gantt-day-col: 72px;
        --gantt-plan-day-col: 72px;
        --danger: #A32D2D;
        --danger-bg: #fcebeb;
        --danger-row-bg: rgba(227,6,19,.13);
        --info: #185fa5;
        --info-bg: #e6f1fb;
        --gantt-cell-bg: #e8eaed;
        --gantt-cell-border: #c9ccd1;
      }
      /* Predvolený 8px margin prehliadača na body nebol nikde resetovaný —
         cez tento okraj presvitalo biele pozadie body (appka naň nikdy
         nenastavovala žiadnu farbu) aj v tmavom režime, keďže --bg sa v
         tmavom režime prepisuje len v rámci .app-shell.dark, nie na body.
         .dark trieda na body (nastavovaná v JS podľa darkMode) drží pozadie
         pod appkou správne aj pri "gumovom" overscrolle. */
      html, body { margin: 0; }
      body { background: #f0f0f0; }
      body.dark { background: #14171a; }
      .app-shell.dark {
        --bg: #14171a;
        --panel: #1e2226;
        --panel-2: #262b30;
        --border: #343b42;
        --text: #e8e6e3;
        --text-dim: #9099a1;
        --accent: #ff4550;
        --accent-dark: #ff6b74;
        --accent-light: rgba(227,6,19,.18);
        --ok: #7cc576;
        --ok-bg: rgba(59,109,17,.28);
        --warn: #e0a858;
        --warn-bg: rgba(133,79,11,.3);
        --danger: #ff6b6b;
        --danger-bg: rgba(163,45,45,.3);
        --danger-row-bg: rgba(255,90,90,.22);
        --info: #6db1e8;
        --info-bg: rgba(24,95,165,.3);
        --gantt-cell-bg: #2c323a;
        --gantt-cell-border: #3f4750;
      }
      .app-shell.dark input, .app-shell.dark select, .app-shell.dark textarea { background: var(--panel-2); }
      .app-shell { background: var(--bg); color: var(--text); min-height: 100vh; font-family: 'Barlow', sans-serif; display: flex; flex-direction: column; padding-top: env(safe-area-inset-top); }

      /* Bočné menu (Požičovňa/Servis/Administratíva + ich záložky). Na webe
         ikonový pás (IconRail nižšie), na mobile text vnútri výsuvnej
         zásuvky (SidebarNav, tá istá trieda .sidebar-nav). Aktívny modul je
         vždy presne ten, čo je "otvorený" (rovnaký stav, žiadny extra) —
         klik na iný modul rovno prepne aj na jeho prvú záložku (setModule to
         už robí), klik na záložku v OTVORENOM module len prepne pohľad. */
      .app-body-row { display: flex; flex: 1; min-height: 0; position: relative; }
      .sidebar-nav { width: 152px; flex-shrink: 0; background: var(--panel); border-right: 1px solid var(--border); padding: 8px 0; overflow-y: auto; }
      /* box-shadow namiesto border-bottom — čiarka sa vykreslí, ale NEPRIDÁ
         výšku navyše (border by pridal 1px, čo by sa v páse muselo naviac
         niečím vykompenzovať — takto netreba). */
      /* Moduly zoskupené hore ako jeden blok, jedna čiara oddeľuje záložky
         AKTUÁLNE otvoreného modulu pod nimi (nie akordeón per modul). */
      .sidebar-modules { box-shadow: 0 1px 0 rgba(0,0,0,.4); padding-bottom: 6px; margin-bottom: 6px; }
      /* Výška 34/29px je NATVRDO rovnaká ako .rail-icon/.rail-row v páse
         nižšie — dve zdieľané konštanty, nie odhad z paddingu/line-height
         (to opakovane nesedelo). Nemení sa jedno bez druhého. */
      .sidebar-group {
        display: flex; align-items: center; gap: 8px; width: 100%; height: 34px; text-align: left; box-sizing: border-box;
        padding: 0 14px; font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 700;
        color: var(--text); background: transparent; border: none; cursor: pointer; border-radius: 6px;
      }
      .sidebar-group.active { color: #fff; background: var(--accent); }
      .sidebar-badge { background: var(--accent); color: #fff; font-size: 10px; border-radius: 99px; padding: 1px 6px; font-weight: 700; }
      .sidebar-group.active .sidebar-badge { background: #fff; color: var(--accent); }
      .sidebar-item {
        display: flex; align-items: center; gap: 6px; width: 100%; height: 29px; text-align: left; box-sizing: border-box;
        padding: 0 14px 0 28px; font-family: 'Barlow', sans-serif; font-size: 12.5px;
        color: var(--text-dim); background: transparent; border: none; cursor: pointer; border-radius: 0;
      }
      .sidebar-item:hover { background: var(--panel-2); }
      .sidebar-item.active { color: var(--accent); background: var(--accent-light); font-weight: 600; }
      .sidebar-subitem { padding-left: 40px; font-size: 12px; }
      .sidebar-subnote { padding: 6px 14px 6px 40px; font-size: 11px; color: var(--text-dim); }
      /* Rýchle akcie (nahlásiť poškodenie/rezervácia/protokol/VTZ EZ) — posledné
         položky v zozname záložiek Požičovne/Servisu, len v IconRail flyoute
         (quickActionsByModule sa do mobilnej zásuvky neposiela). */
      /* Len tenká čiarka (box-shadow, nie border — ten by pridal 1px výšky
         navyše, čo pás nemá čím vykompenzovať). */
      .sidebar-quick { box-shadow: inset 0 1px 0 var(--border); }
      .sidebar-group.rail-ask { color: #e6392e; font-weight: 700; background: #1a1a1a; border-radius: 6px; margin-bottom: 10px; }
      .sidebar-group.rail-ask:hover { background: #2b2b2b; }
      .sidebar-group.rail-ask svg { flex-shrink: 0; }
      /* 34px riadok (nie 29 ako bežná .sidebar-item) — presne ako 34px
         ikonka rýchlej akcie v IconRail páse. */
      .sidebar-item.quick { height: 34px; color: var(--accent); font-weight: 600; }

      /* IconRail — úzky pás ikon na webe namiesto trvalo roztiahnutého
         bočného menu (nezaberá šírku plochy). Farba záhlavia, nech je hneď
         jasné, že je to "menu appky", nie ďalší biely panel. Prejdením myšou
         cez ikonu modulu sa vysunie panel so záložkami (rail-flyout) cez
         plochu, nie natrvalo vedľa nej. Rýchle akcie (poškodenie/rezervácia/
         protokol/VTZ EZ) sú dole za deliacou čiarou, menšie a kruhové —
         zámerne odlíšené, nejde o navigáciu ale o akcie. */
      /* .icon-rail-wrap je len dištančná medzera vo flex riadku (.app-body-row),
         drží 52px šírky, nič nevykresľuje. Samotný pás (.icon-rail) aj vysunuté
         menu (.rail-flyout) sú position:fixed, ukotvené priamo na viewport od
         (JS zmeraného) vrchu po úplný spodok — height:100%/sticky tu totiž
         spoliehalo na to, že .app-body-row má definitnú výšku "zvyšok
         obrazovky pod headerom", čo platí LEN keď je stránka presne na výšku
         obrazovky. Pri dlhšom obsahu (napr. dlhý zoznam strojov), ktorý
         naťahuje celý dokument a scrolluje sa celá stránka, je .app-body-row
         vysoká ako OBSAH, nie ako viditeľná plocha — spodok pásu (telefón/
         pripomienka) tak vždy "utiekol" mimo obraz. Fixed (top nastavený z
         IconRail cez inline style, viď wrapRef/railTop) to rieši úplne. */
      .icon-rail-wrap { width: 52px; flex-shrink: 0; }
      /* Bez gap medzi riadkami — presne ako vo flyoute (.rail-flyout-nav), kde
         nadpis modulu a jeho záložky/akcie tiež nasledujú tesne za sebou bez
         medzery. Výška každého typu riadku (.rail-row 29px, ikona modulu
         34px) zodpovedá skutočnej výške riadku vo flyoute (.sidebar-group
         ~34px, .sidebar-item ~29px), nech si sedia 1:1 aj vizuálne, nielen
         počtom. Padding hore 8px = to isté, čo .rail-flyout-nav. */
      /* Svetlý režim: biely pás + biele vysunuté menu, oddelené od plochy
         červenou linkou, čierne ikony/bodky, zvolený modul = biela ikona v
         červenej bubline, zvolená záložka = biela bodka s červeným rámikom.
         Tmavý režim (.app-shell.dark nižšie) má vlastnú, nezmenenú paletu —
         tmavosivý pás, biele/priesvitné ikony, červený pásik namiesto bubliny. */
      .icon-rail { position: fixed; left: 0; bottom: 0; width: 52px; background: var(--panel); border-right: 1px solid var(--border); display: flex; flex-direction: column; align-items: center; padding: 8px 0; box-sizing: border-box; z-index: 50; isolation: isolate; }
      /* Scrollovateľná časť pásu (moduly/záložky) — flex:1 necháva zvyšné
         miesto pre .rail-bottom-actions POD ňou, mimo scrollu, takže telefón
         a pripomienka sú vždy vidno vizuálne na spodku, nie len "za
         posledným riadkom" pri krátkom obsahu. */
      .rail-scroll { width: 100%; flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; align-items: center; }
      /* Plná šírka pásu (nie len 34px šírka ikony), nech je čiara pod modulmi
         dobre vidno — box-shadow namiesto border, nech nepridáva výšku navyše. */
      .rail-modules { width: 100%; display: flex; flex-direction: column; align-items: center; box-shadow: 0 1px 0 rgba(0,0,0,.4); padding-bottom: 6px; margin-bottom: 6px; }
      .rail-icon {
        width: 34px; height: 34px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
        color: var(--text-dim); background: transparent; border: none; cursor: pointer; position: relative; flex-shrink: 0; padding: 0;
        transition: background .15s ease, color .15s ease;
      }
      .rail-icon:hover { background: var(--panel-2); color: var(--text); }
      .rail-icon.active { color: #fff; background: var(--accent); }
      .rail-icon.active:hover { color: #fff; }
      /* Skratky modulov (POŽ/SRV/ADM) namiesto SVG ikon — rovnaký box ako
         .rail-icon, len s textom. */
      .rail-icon-label { font-family: 'Barlow Condensed', 'Barlow', sans-serif; font-size: 11px; font-weight: 700; letter-spacing: .02em; }
      /* Jeden riadok = jeden riadok vo flyoute (záložka = bodka, rýchla akcia
         = červená ikona) — 29px, presne ako .sidebar-item tam (zdieľaná
         konštanta, viď komentár pri .sidebar-item). */
      .rail-row {
        width: 34px; height: 29px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;
        background: transparent; border: none; padding: 0; border-radius: 6px; cursor: pointer;
      }
      .rail-row:disabled { cursor: default; }
      .rail-row:hover:not(:disabled) { background: var(--panel-2); }
      .rail-row-quick { height: 34px; }
      /* Rovnako veľké ako ikony modulov (34px), nech sú dobre vidno. */
      .rail-icon.quick { width: 34px; height: 34px; border-radius: 50%; color: var(--text-dim); }
      .rail-icon.quick svg { width: 18px; height: 18px; }
      .rail-icon.quick:hover { background: var(--panel-2); }
      /* výnimka — "Čo vyriešiť dnes?" nie je rýchla akcia modulu, čierny box + červená bublina, jednoznačne oddelené */
      .rail-icon.quick.rail-ask { color: #e6392e; background: #1a1a1a; border-radius: 8px; margin-bottom: 10px; }
      .rail-icon.quick.rail-ask:hover { background: #2b2b2b; }
      .rail-tick { width: 6px; height: 6px; border-radius: 50%; background: var(--text); opacity: .35; flex-shrink: 0; box-sizing: border-box; }
      .rail-tick.active { width: 8px; height: 8px; background: #fff; border: 2px solid var(--accent); opacity: 1; }
      /* rovnaká deliaca čiara ako vo flyoute (.sidebar-quick), box-shadow →
         nezaberá výšku, nerozhodí zarovnanie s textom (moduly/tabs čiaru má
         .rail-modules vyššie) */
      .rail-divider-before { box-shadow: inset 0 1px 0 var(--border); }
      /* Telefón/pripomienka celkom dole v úzkom páse — MIMO .rail-scroll
         vyššie (nie sticky vnútri neho), takže sú vždy vizuálne na spodku
         pásu, nezávisle od toho, koľko riadkov má aktívny modul nad nimi. */
      .rail-bottom-actions {
        width: 100%; flex-shrink: 0;
        display: flex; flex-direction: column; align-items: center; gap: 2px;
        padding-top: 6px; box-shadow: inset 0 1px 0 var(--border);
      }
      .rail-icon.quick.rail-bottom-icon { color: var(--accent); }
      .rail-badge {
        position: absolute; top: -2px; right: -2px; background: #fff; color: var(--accent);
        font-size: 9px; font-weight: 700; border-radius: 99px; min-width: 14px; height: 14px;
        padding: 0 3px; display: flex; align-items: center; justify-content: center; line-height: 1;
      }
      .rail-flyout {
        /* 260px, nie 205 — pri 205 sa "Poškodenia strojov požičovne" a "Záznam
           z merania VTZ EZ" zalamovali na 2 riadky. Len tieň, žiadna deliaca
           linka (tú má len samotný úzky pás vľavo, .icon-rail). */
        position: fixed; left: 52px; bottom: 0; width: 260px; background: var(--panel);
        border-right: 1px solid var(--border); box-shadow: 4px 0 16px rgba(0,0,0,.10); z-index: 50;
        display: flex; flex-direction: column;
        opacity: 0; transform: translateX(-10px); pointer-events: none;
        transition: opacity .22s cubic-bezier(0.16, 1, 0.3, 1), transform .22s cubic-bezier(0.16, 1, 0.3, 1);
      }
      .rail-flyout.rail-flyout-open { opacity: 1; transform: translateX(0); pointer-events: auto; }
      /* Scrollovateľná časť (moduly/záložky) — flex:1 necháva zvyšný priestor
         pre .rail-flyout-bottom POD ňou, mimo scrollu, nech telefón a
         pripomienka zostanú vždy vizuálne na spodku vysunutého menu. */
      .rail-flyout-scroll {
        width: 100%; flex: 1; min-height: 0; overflow-y: auto;
        /* horný padding je TU, nie na .rail-flyout-nav — musí platiť aj pre
           tlačidlo "Čo vyriešiť dnes?" nad ním, inak je o 8px vyššie než
           zodpovedajúca ikona bubliny v .icon-rail (tá má padding-top tiež
           na vonkajšom kontajneri, nie až pri prvej ikone). */
        padding-top: 8px;
      }
      .rail-flyout-nav { width: 100%; padding: 0 0 8px; }
      /* Riadky 34px + gap 2px + padding 6px hore / 8px dole — rovnaké čísla
         ako .rail-bottom-actions v úzkom páse (padding-top 6, gap 2, a 8px
         padding-bottom prevzaté z .icon-rail), nech si telefón/pripomienka
         sadnú 1:1 s ikonami vedľa, nielen počtom riadkov. */
      .rail-flyout-bottom { width: 100%; flex-shrink: 0; display: flex; flex-direction: column; gap: 2px; padding: 6px 0 8px; box-shadow: inset 0 1px 0 var(--border); }
      .rail-flyout-bottom .sidebar-item { padding-left: 14px; }

      /* Tmavý režim — pôvodná tmavosivá paleta, nemení sa. */
      .app-shell.dark .icon-rail { background: #22262b; border-right: none; }
      .app-shell.dark .rail-icon { color: rgba(255,255,255,.55); }
      .app-shell.dark .rail-icon:hover { color: rgba(255,255,255,.85); background: transparent; }
      .app-shell.dark .rail-icon.quick { color: var(--accent); }
      .app-shell.dark .rail-icon.active { color: #fff; background: transparent; }
      .app-shell.dark .rail-icon.active::before { content: ""; position: absolute; left: -8px; top: 5px; bottom: 5px; width: 3px; border-radius: 2px; background: var(--accent); }
      .app-shell.dark .rail-tick { background: rgba(255,255,255,.32); opacity: 1; }
      .app-shell.dark .rail-tick.active { background: #fff; border-color: var(--accent); }

      /* Tabuľka (.table-cards) sa na mobile prekreslí na kartičky — každý
         riadok = jedna karta, buňky pod sebou ako "label: hodnota" (label z
         data-label atribútu, keď ho buňka má). Webové zobrazenie (bežná
         tabuľka) je nezmenené, toto platí len pod @media nižšie. */
      @media (max-width: 720px) {
        table.table-cards thead { display: none; }
        table.table-cards, table.table-cards tbody { display: block; width: 100%; }
        table.table-cards tr { display: block; margin-bottom: 10px; border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px; background: var(--panel); }
        table.table-cards td { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 5px 0; border: none; text-align: right; }
        table.table-cards td[data-label]::before { content: attr(data-label); font-size: 11px; font-weight: 600; color: var(--text-dim); text-align: left; margin-right: auto; flex-shrink: 0; }
        table.table-cards td.td-plain { display: block; text-align: left; }
        table.table-cards td.td-actions { justify-content: flex-end; }
        /* Vstupy/selecty v karte majú na desktope pevnú (úzku) šírku pre
           tabuľkový layout — na mobile namiesto toho vyplnia zvyšok riadku
           vedľa labelu, nech sa nemusí posúvať do boku ani pri dlhších
           hodnotách (popis dielu a pod.). */
        table.table-cards td input, table.table-cards td select { width: 100% !important; max-width: 200px; }
        /* Riadkové akcie (Zmazať a pod.) v karte — väčšie dotykové pole než
           na desktope, nech sa na mobile dá bezpečne trafiť prstom. */
        table.table-cards td.td-actions button { min-height: 36px; padding: 6px 14px !important; }
      }

      /* Položka v kebab (⋮) menu — riadkové akcie skryté za jedným tlačidlom
         namiesto radu btn-ghost tlačidiel v tabuľke/karte. */
      .kebab-item {
        display: block; width: 100%; text-align: left; background: transparent; border: none;
        padding: 8px 10px; font-size: 13px; font-family: 'Barlow', sans-serif; cursor: pointer;
        border-radius: 5px; text-decoration: none;
      }
      .kebab-item:hover { background: var(--panel-2); }

      /* "Vlajočka" prilepená na ľavom okraji obrazovky — otvorí to isté menu ako
         výsuvný panel — len na mobile (nižšie v @media). Na webe je bočné menu
         trvalo viditeľné (IconRail), vlajočku tam netreba. Úzka a nízka (tenká
         šípka, nie veľké tlačidlo), väčšina trčí mimo obrazovky, nech
         nezasahuje do plochy pod ňou. */
      .mobile-nav-edge-flag {
        display: none; position: fixed; left: -14px; top: 50%; transform: translateY(-50%);
        align-items: center; justify-content: center;
        width: 22px; height: 46px; padding-left: 10px; border-radius: 0 8px 8px 0;
        background: var(--accent); border: none; color: #fff; font-size: 13px; cursor: pointer;
        box-shadow: 2px 0 8px rgba(0,0,0,.18); z-index: 90;
      }
      .mobile-nav-overlay { position: fixed; inset: 0; z-index: 300; display: flex; }
      .mobile-nav-scrim { position: absolute; inset: 0; background: rgba(0,0,0,.4); }
      /* width:100% (nie pevných 152px ako .sidebar-nav) — pri dlhších názvoch
         záložiek ("Poškodenia strojov požičovne") sa inak zalamovali na 2-3
         riadky v pevnej výške riadku a prekrývali susedný riadok pod sebou
         (presne ten istý problém, čo mal kedysi aj .rail-flyout — viď jeho
         komentár pri width:260px vyššie). height:auto na riadkoch je poistka
         pre prípad, že by sa aj tak zalomili na najužších telefónoch. */
      .mobile-nav-drawer {
        position: relative; width: 64%; max-width: 240px; background: var(--panel);
        height: 100%; overflow-y: auto; box-shadow: 4px 0 16px rgba(0,0,0,.10);
        padding-top: env(safe-area-inset-top);
        display: flex; flex-direction: column;
      }
      .mobile-nav-scroll { flex: 1 1 auto; overflow-y: auto; }
      /* Meno/nastavenia je vždy prilepené celkom dole v drawri (margin-top:
         auto), aj keď je menu krátke a nevyplní celú výšku. */
      .mobile-nav-footer { margin-top: auto; padding: 10px; border-top: 1px solid var(--border); }
      .mobile-nav-drawer .sidebar-nav { width: 100%; }
      .mobile-nav-drawer .sidebar-group, .mobile-nav-drawer .sidebar-item { height: auto; min-height: 29px; white-space: normal; padding-top: 6px; padding-bottom: 6px; font-size: 13px; }
      /* Okamžitý tooltip nad blokom zákazky/rezervácie v Gantte — namiesto pomalého
         natívneho (title) sa objaví hneď pri prejdení myšou, čisto cez CSS.
         Zámerne NIŽŠIE ako .gantt-name-wrap (meno stroja), a to aj pri
         nabehnutí myšou — inak by zákazka pri nabehnutí myšou (keď "vyskočí"
         kvôli vlastnému tooltipu) prekryla meno stroja v tom istom riadku. */
      .gantt-bar-wrap { position: relative; z-index: 1; }
      .gantt-bar-wrap:hover { z-index: 10; }
      /* Meno stroja (prvý stĺpec) — musí byť VŽDY nad zákazkami, aj tými, čo
         práve "vyskočili" pri nabehnutí myšou (10 vyššie) — preto tu základná
         hodnota (20) už sama o sebe prevyšuje aj tamten najvyšší prípad. */
      .gantt-name-wrap { position: relative; z-index: 20; }
      .gantt-name-wrap:hover { z-index: 30; }
      .gantt-tooltip {
        visibility: hidden;
        opacity: 0;
        position: absolute;
        bottom: 100%;
        left: 0;
        margin-bottom: 5px;
        background: #1a1a1a;
        color: #fff;
        font-size: 11px;
        line-height: 1.4;
        padding: 7px 10px;
        border-radius: 6px;
        white-space: normal;
        width: max-content;
        max-width: 260px;
        z-index: 50;
        pointer-events: none;
      }
      .gantt-bar-wrap:hover .gantt-tooltip, .gantt-name-wrap:hover .gantt-tooltip, .gantt-transport-icon:hover .gantt-tooltip { visibility: visible; opacity: 1; }
      /* Ťahanie zákazky/rezervácie v Gantte (presun/zmena termínu) — stredná
         časť bloku = kurzor "uchopiť" (presun), tenké 8px pruhy na okrajoch =
         kurzor na zmenu šírky (zmena len začiatku/konca). Samotné ťahanie
         nižšie priamo mutuje DOM (style.gridColumn), nie React stav — tieto
         handle prvky sú len vizuálna/klikacia vrstva nad tým. */
      .gantt-bar-wrap.draggable { cursor: grab; }
      .gantt-bar-wrap.draggable:active { cursor: grabbing; }
      .gantt-drag-handle { position: absolute; top: 0; bottom: 0; width: 8px; cursor: ew-resize; z-index: 5; }
      .gantt-drag-handle.start { left: 0; }
      .gantt-drag-handle.end { right: 0; }
      /* Ikonka skutočného vývozu/zvozu (odlišného od zmluvného dátumu) — čisto
         vizuálna, nezasahuje do klikov na samotnú zákazku pod ňou. */
      /* Bez vlastného z-index na tomto boxe (len position:relative ako kotva
         pre tooltip) — icon tak zostáva v "auto" vrstve, VŽDY za menom
         stroja (to má z-index:2, teda vyššiu explicitnú vrstvu), zatiaľ čo
         jeho .gantt-tooltip (z-index:50) sa vie normálne vyšvihnúť nad
         VŠETKY riadky, lebo nie je zamknutý v nízkej lokálnej "stacking
         context" tohto boxu. */
      .gantt-transport-icon { position: relative; display: flex; align-items: center; justify-content: center; gap: 3px; font-size: 10px; font-weight: 600; color: #1a1a1a; pointer-events: auto; cursor: default; line-height: 1; }
      .app-shell.dark .gantt-transport-icon { color: #fff; }
      /* Kývajúca ruka panáčika na uvítacej obrazovke (LiftLoader) — transform-origin
         zámerne BEZ transform-box: fill-box (pre <g> s len obrysovými čiarami,
         bez "fill" geometrie, si to niektoré prehliadače spočítajú s nulovým
         rozmerom a ruka potom zmizne — bez neho sa origin berie z vlastných
         súradníc SVG, presne ako pri zdvíhaní nožníc vyššie). */
      @keyframes mascot-wave { 0%, 100% { transform: rotate(-16deg); } 50% { transform: rotate(16deg); } }
      .mascot-wave-arm { transform-origin: 371px 462px; animation: mascot-wave 1s ease-in-out infinite; }
      .label-font { font-family: 'Barlow Condensed', sans-serif; }
      .mono { font-family: 'Barlow', sans-serif; font-weight: 700; letter-spacing: .01em; }
      .panel { background: var(--panel); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 2px 12px rgba(0,0,0,.06); }
      .mobile-tech-actions { display: none; }
      .btn { padding: 7px 14px; border-radius: 6px; font-family: 'Barlow', sans-serif; font-weight: 600; font-size: 13px; cursor: pointer; border: 1px solid transparent; transition: .15s; display: inline-block; text-decoration: none; }
      .btn-accent { background: var(--accent); color: #fff; }
      .btn-accent:hover { background: var(--accent-dark); }
      .btn-accent:disabled { opacity: .4; cursor: not-allowed; }
      .btn-ghost { background: transparent; border: 1px solid var(--border); color: var(--text); }
      .btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
      .badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-family: 'Barlow', sans-serif; text-transform: uppercase; font-size: 10px; font-weight: 700; letter-spacing: .04em; }
      .badge-ok { background: var(--ok-bg); color: var(--ok); }
      .badge-warn { background: var(--warn-bg); color: var(--warn); }
      .badge-danger { background: var(--danger-bg); color: var(--danger); }
      .badge-info { background: var(--info-bg); color: var(--info); }
      /* Zdieľaný "počítací" odznak (aktívne filtre a pod.) — jeden radius/
         veľkosť namiesto toho, aby si ho každé miesto vyrábalo nanovo. */
      .count-badge { display: inline-flex; align-items: center; justify-content: center; background: var(--accent); color: #fff; font-size: 10px; border-radius: 10px; min-width: 16px; height: 16px; padding: 0 5px; font-weight: 700; line-height: 1; }
      /* Zdieľané "×" tlačidlo na zatvorenie — tlmené (žiadne pozadie v pokoji,
         jemné pri hoveri), rovnaký jazyk ako .rail-icon namiesto textového
         tlačidla "Zavrieť" alebo červeného kruhu. */
      .modal-close-x {
        width: 30px; height: 30px; border-radius: 8px; display: flex; align-items: center; justify-content: center;
        background: transparent; border: none; color: var(--text-dim); font-size: 22px; line-height: 1; cursor: pointer;
        transition: background .15s ease, color .15s ease; flex-shrink: 0;
      }
      .modal-close-x:hover { background: var(--panel-2); color: var(--text); }
      /* Toast s potvrdením odoslania — hore na strede, sám zmizne po pár
         sekundách. z-index 250: nad kartami (160/170), pod dropdown/notif. (200+). */
      .app-toast {
        position: fixed; top: 12px; left: 50%; transform: translateX(-50%); z-index: 250;
        background: var(--ok); color: #fff; padding: 9px 16px; border-radius: 8px;
        font-size: 13px; font-weight: 600; box-shadow: 0 4px 16px rgba(0,0,0,.15);
        animation: app-toast-in .2s ease;
      }
      @keyframes app-toast-in { from { opacity: 0; transform: translate(-50%, -8px); } to { opacity: 1; transform: translate(-50%, 0); } }
      /* Karty s "eyebrow" titulkom (identita — zákazka, rezervácia, stroj,
         zákazník, auto) — horný toolbar riadok oddelený čiarou, mierne
         záporný margin nech siaha až po okraj panelu ako pri iných kartách. */
      .modal-toolbar { display: flex; align-items: center; justify-content: flex-end; gap: 10px; flex-wrap: wrap; margin: -20px -20px 14px; padding: 8px 12px; border-bottom: 1px solid var(--border); }
      .modal-title-block { margin-bottom: 16px; }
      .modal-eyebrow { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .03em; color: var(--text-dim); margin-bottom: 2px; }
      .modal-title-main { font-size: 17px; font-weight: 700; color: var(--text); line-height: 1.25; margin: 0; }
      input, select, textarea { background: #fff; border: 1.5px solid var(--border); color: var(--text); border-radius: 6px; padding: 7px 10px; font-size: 14px; font-family: 'Barlow', sans-serif; }
      input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgba(227,6,19,.08); }
      table { width: 100%; border-collapse: collapse; }
      th { text-align: left; font-family: 'Barlow', sans-serif; text-transform: uppercase; font-size: 10px; font-weight: 700; letter-spacing: .05em; color: var(--text-dim); padding: 10px; border-bottom: 1px solid var(--border); white-space: nowrap; background: var(--panel-2); }
      td { padding: 9px 10px; border-bottom: 1px solid var(--border); font-size: 13px; }
      tr:hover td { background: var(--accent-light); }

      /* ══════════════════════════════════════════════════════
         MOBILE — telefóny a malé tablety
         ══════════════════════════════════════════════════════ */
      @media (max-width: 720px) {
        /* iOS "gumové" posúvanie stránky mimo obrazovku (najmä šikmým ťahom prsta) —
           len na mobile, na PC by to blokovalo bežné rolovanie kolieskom/scrollbarom. */
        html, body { overscroll-behavior: none; overflow-x: hidden; }

        /* To isté pre servisný protokol — len na mobile, nech na PC ide bežné
           rolovanie kolieskom myši (predtým sa toto omylom aplikovalo vždy). */
        .protocol-overlay { overscroll-behavior: none; touch-action: pan-y; }

        /* Zvonček a menu používateľa — na mobile sa pripnú k okraju obrazovky
           namiesto malej ikonky, nech sa nikdy nezobrazia mimo viditeľnej plochy. */
        .dropdown-panel {
          position: fixed !important;
          left: 8px !important;
          right: 8px !important;
          top: calc(62px + env(safe-area-inset-top)) !important;
          width: auto !important;
          max-width: none !important;
        }

        /* Tlačidlá pre technikov (Vypísať protokol, VTZ EZ...) — na mobile
           naťahovali hlavičku a zalamovali sa nečitateľne. Namiesto toho sa
           tam schovajú a zobrazí sa pevný pásik dole na obrazovke. */
        .header-tech-actions { display: none !important; }
        .mobile-tech-actions {
          display: flex !important;
          position: fixed;
          left: 0;
          right: 0;
          bottom: 0;
          z-index: 150;
          gap: 6px;
          padding: 6px 8px calc(6px + env(safe-area-inset-bottom)) 8px;
          background: var(--panel);
          border-top: 1px solid var(--border);
          box-shadow: 0 -2px 8px rgba(0,0,0,.08);
        }
        .mobile-tech-action-btn {
          flex: 1;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          gap: 2px;
          padding: 8px 4px;
          min-height: 52px;
          border-radius: 8px;
          background: var(--panel-2);
          color: var(--text);
          text-decoration: none;
          font-family: 'Barlow', sans-serif;
          font-size: 11px;
          font-weight: 600;
          border: 1px solid var(--border);
        }
        .mobile-tech-action-accent {
          background: var(--accent);
          color: #fff;
          border-color: var(--accent);
        }
        .mobile-tech-action-icon { font-size: 18px; line-height: 1; }
        .app-main.has-mobile-tech-bar { padding-bottom: calc(76px + env(safe-area-inset-bottom)) !important; }

        /* maSKot bublina — na mobile by inak sedela presne v spodnej lište
           s tlačidlami pre technikov (keby mal daný účet aj tie práva) a
           prekrývala by ich. Posunutá vyššie vždy, nech je to jednoduché a
           spoľahlivé aj keď lišta zrovna nie je zobrazená. */
        .maskot-fab { bottom: calc(20px + 76px + env(safe-area-inset-bottom)) !important; }
        .maskot-panel { bottom: calc(82px + 76px + env(safe-area-inset-bottom)) !important; }

        /* To isté pre bublinu "čaká na zobrazenie" (skok na zvýraznené poškodenie). */
        .damage-toast-fab { bottom: calc(20px + 76px + env(safe-area-inset-bottom)) !important; }

        /* IconRail (hover) nedáva na dotykovej obrazovke zmysel — na mobile
           namiesto neho hamburger v hornej lište otvorí to isté menu ako
           výsuvný panel (mobile-nav-drawer, mimo tohto breakpointu vyššie,
           tá istá trieda .sidebar-nav ale vnútri drawera zostáva viditeľná). */
        .icon-rail-wrap { display: none; }
        .mobile-nav-edge-flag { display: flex; }

        :root {
          --gantt-name-col: 92px;
          /* 53px — na užšom mobile (~331px na dni po odčítaní stĺpca s menom)
             vidno naraz cca 4,5 dňa. Na širšom mobile/tablete v tomto istom
             breakpointe to logicky ukáže viac dní naraz, lebo je tam viac
             miesta — rovnaká šírka bunky, len viac sa ich zmestí. */
          --gantt-day-col: 53px;
          --gantt-plan-day-col: 46px;
        }
        .app-main { padding: 10px !important; }
        /* flex-wrap ostáva "wrap" (nie nowrap) — je to poistka: ak by sa aj
           napriek nižšiemu doplneniu niečo nezmestilo, nech sa to zalomí na
           ďalší riadok, nie aby to odrezalo/schovalo zvonček mimo obrazovky
           (presne to sa predtým dialo s vynúteným nowrap). */
        .header-topbar { padding: 7px 10px !important; gap: 6px !important; }
        .header-navbar { padding: 7px 10px !important; gap: 8px !important; }
        /* Popis platformy + verzia — na mobile vlastný (druhý) riadok POD
           logom (order + flex-basis:100%), nech na PRVOM riadku (logo,
           vyhľadávanie, zvonček) ostane vždy dosť miesta. */
        .header-brand-sub { order: 3; flex-basis: 100%; margin-top: 1px; }
        .header-divider { display: none !important; }
        .header-subtitle { display: block !important; font-size: 9px !important; white-space: nowrap; }
        .user-menu-desktop-wrap { display: none !important; }
        .header-top-actions { gap: 5px !important; }
        .header-top-actions button, .header-top-actions label, .header-top-actions select, .header-top-actions > div {
          font-size: 10px !important;
          padding: 4px 6px !important;
        }
        /* Zvonček — samotný text/ikonový obsah je malý, ale dotykové pole
           okolo neho nech je aspoň ~40px (odporúčaná min. veľkosť na dotyk),
           inak sa naň na mobile ťažko trafí. */
        .header-top-actions button { min-height: 38px; min-width: 38px; }
        .global-search-box { min-width: 70px !important; }
        .global-search-box input { font-size: 12px !important; padding: 4px 8px !important; }
        .panel { padding: 12px !important; }
        /* display:flex tu MUSÍ byť tiež !important — kalendár požičovne má
           túto lištu nastavenú inline ako display:"grid" (3 stĺpce vedľa
           seba), čo sa nikdy nezalomí na užšom telefóne bez ohľadu na
           flex-wrap (tá vlastnosť na grid kontajner nemá vôbec žiaden efekt).
           Preto v portraite miznú/orezávajú sa tlačidlá napravo (→, Dnes,
           Normálny/Kompaktný) — grid stĺpce sa len stlačia/pretečú, nezalomí
           sa to na ďalší riadok tak ako pri flexboxe. */
        .quick-filters { display: flex !important; flex-wrap: wrap !important; }

        /* Info-grid karty (Karta stroja, zákazky, šoféra, technika…) — jeden stĺpec pod sebou */
        .resp-grid { grid-template-columns: 1fr !important; }

        /* Modálne okná — takmer celá obrazovka, menší padding */
        .modal-overlay { padding: 0 !important; align-items: stretch !important; }
        .modal-panel { width: 100% !important; max-width: 100% !important; min-height: 100vh; border-radius: 0 !important; padding: 12px !important; padding-top: max(12px, env(safe-area-inset-top)) !important; padding-bottom: max(12px, env(safe-area-inset-bottom)) !important; }
        /* Len -12px hore (nie aj safe-area-inset-top ako predtým) — inak sa
           táto lišta (má v sebe zatváracie ×) vytiahla úplne až za stavový
           riadok telefónu a × sa dala schovať za hodiny/batériu, nedalo sa
           na ňu kliknúť. Safe-area medzera nad ňou tak ostáva zachovaná. */
        .modal-toolbar { margin: -12px -12px 14px !important; }
        .modal-header h3 { font-size: 15px !important; }
        .modal-title-main { font-size: 15px !important; }
        /* Krížik na zatvorenie — 30px je na dotyk malé, na mobile väčší. */
        .modal-close-x { width: 40px !important; height: 40px !important; font-size: 26px !important; }

        /* Tabuľky — radšej vodorovné rolovanie vnútri panelu než rozbitie stránky.
           Zámerne LEN pre panely s tabuľkou (:has), nie pre všetky .panel —
           overflow-x:auto totiž podľa CSS špecifikácie automaticky prepne aj
           overflow-y na "auto" (ak nie je nastavené inak), a to vedelo
           orezať/schovať rozbaľovacie zoznamy (dropdown), ktoré vnútri iného
           .panel (napr. filter/search panela) siahajú POD jeho okraj —
           presne ten efekt, čo vyzeral ako "odlepený"/zmiznutý dropdown. */
        .panel:has(table) { overflow-x: auto; }
        table { font-size: 11px; }
        th, td { padding: 6px 7px !important; }
        table th:first-child, table td:first-child {
          position: sticky;
          left: 0;
          background: var(--panel);
          z-index: 1;
          box-shadow: 2px 0 4px rgba(0,0,0,.08);
        }

        /* Väčšie, na dotyk pohodlnejšie tlačidlá */
        .btn { padding: 7px 11px; font-size: 12px; }

        /* Formulárové polia nech nikdy nepretečú cez okraj obrazovky */
        input, select, textarea { min-width: 0 !important; max-width: 100%; font-size: 13px; }

        h3.label-font { word-break: break-word; }

        /* Zákazky — rýchle rozbaľovacie zoznamy (po termíne/končí čoskoro/bez šoféra) */
        .quick-job-row { flex-direction: column !important; align-items: flex-start !important; gap: 6px !important; }
        .quick-job-info { font-size: 12px !important; }
        .quick-job-info .mono { font-size: 12px !important; }
        .quick-job-btn { margin-left: 0 !important; width: 100%; }

        /* Gantty (Kalendár, Plán servisu) — kompaktnejšie stĺpce, menšie písmo */
        .gantt-cell { font-size: 9px !important; }
        .gantt-header-cell { font-size: 9px !important; padding: 2px !important; }

        /* Vypísanie protokolu — na mobile naozaj cez celú obrazovku, žiadny okraj
           navyše, nech je čo najviac miesta na samotné vypĺňanie. */
        /* Odsadenie od stavového riadku telefónu si dnes rieši priamo
           ProtocolModal/PrintProtocolModal (inline štýl na .protocol-frame-wrap),
           .protocol-overlay samotný už žiadny padding navyše nepotrebuje/nesmie
           mať (zdvojilo by odsadenie). */
        .protocol-frame-wrap { border-radius: 0 !important; }
      }

      @media (max-width: 480px) {
        .header-topbar span.label-font { font-size: 17px !important; }
      }

    `}</style>
  );
}

// Čaká na jednorazový zdvih plošiny (riseMs) AJ na skutočné načítanie appky —
// podľa toho, čo trvá dlhšie. Ak sa appka načíta skôr, plošina si pokojne
// dobehne celý zdvih hore; ak trvá načítanie appky dlhšie, plošina hore
// jednoducho počká, nedvíha sa a nespúšťa dookola. isLoading musí pri každej
// novej fáze (napr. "načítavam dáta" → "načítavam profil") prejsť cez false,
// aby sa pri ďalšom "true" začal počítať nový zdvih od začiatku.
function useRiseThenReveal(isLoading, riseMs) {
  const [visible, setVisible] = useState(isLoading);
  const startRef = useRef(isLoading ? Date.now() : null);
  useEffect(() => {
    if (isLoading) {
      if (startRef.current === null) startRef.current = Date.now();
      setVisible(true);
      return;
    }
    if (startRef.current === null) {
      setVisible(false);
      return;
    }
    const remaining = riseMs - (Date.now() - startRef.current);
    if (remaining <= 0) {
      setVisible(false);
      startRef.current = null;
      return;
    }
    const timer = setTimeout(() => {
      setVisible(false);
      startRef.current = null;
    }, remaining);
    return () => clearTimeout(timer);
  }, [isLoading, riseMs]);
  return visible;
}

// Kontrola novej verzie appky — na rozdiel od prvej verzie tejto kontroly
// (čo appku hneď a potichu reštartovala) toto len NAHLÁSI, že je dostupná
// nová verzia, a nechá človeka rozhodnúť, kedy si to obnoví — nikdy to
// nespraví samo uprostred rozrobenej práce (napr. rozpísaný protokol).
// Kontroluje sa raz pri načítaní appky, a potom vždy znova, keď sa appka/karta
// vráti do popredia (odomknutie telefónu, prepnutie späť na kartu) — presne
// vtedy je najväčšia šanca, že technik nič práve nevypĺňa.
function useNewVersionCheck() {
  const [newVersionAvailable, setNewVersionAvailable] = useState(false);
  const pendingVersionRef = useRef(null);
  useEffect(() => {
    const STORAGE_KEY = "mateco_app_version";
    function check() {
      fetch(`${import.meta.env.BASE_URL}version.json?t=${Date.now()}`, { cache: "no-store" })
        .then((res) => (res.ok ? res.json() : null))
        .then((data) => {
          if (!data || !data.v) return;
          const stored = localStorage.getItem(STORAGE_KEY);
          if (!stored) {
            localStorage.setItem(STORAGE_KEY, data.v);
            return;
          }
          if (stored !== data.v) {
            pendingVersionRef.current = data.v;
            setNewVersionAvailable(true);
          }
        })
        .catch(() => {
          // Bez pripojenia alebo iná chyba — skúsi to znova nabudúce.
        });
    }
    check();
    function onVisible() {
      if (document.visibilityState === "visible") check();
    }
    document.addEventListener("visibilitychange", onVisible);
    return () => document.removeEventListener("visibilitychange", onVisible);
  }, []);
  function applyNewVersion() {
    if (!pendingVersionRef.current) return;
    localStorage.setItem("mateco_app_version", pendingVersionRef.current);
    const url = new URL(window.location.href);
    url.searchParams.set("_v", pendingVersionRef.current);
    window.location.replace(url.toString());
  }
  return { newVersionAvailable, applyNewVersion };
}

// Nožnicová plošina (4 stupne, v štýle veľkého teleskopického modelu ako
// GS-5390) — zdvihne sa RAZ, zdola nahor, a hore ostane stáť, kým appka
// nie je pripravená. Mechanizmus je vykreslený POD podvozkom (v poradí
// scissor → chassis), nech vyzerá, že nožnice vychádzajú znútra podvozku,
// nie že sú položené pred ním.
function LiftLoader({ label }) {
  const [risen, setRisen] = useState(false);
  useEffect(() => {
    const raf = requestAnimationFrame(() => setRisen(true));
    return () => cancelAnimationFrame(raf);
  }, []);
  const rise = "transform 2.4s cubic-bezier(.2,.7,.3,1)";
  // Skutočná príčina prestrekávania: vrch cik-caku (pôvodne y=60) bol podľa
  // pevných súradníc o 24px VYŠŠIE než spodný okraj koša v pokojovej polohe
  // (y=84) — nezávisle od animácie, trvalo, aj v pokoji. Prepočítané tak, aby
  // vrch cik-caku (teraz y=84, rovnomerne rozostúpené kroky po 99px namiesto
  // 105px) presne sadol na spodný okraj koša pri každom snímku animácie
  // (zloženého aj rozťiahnutého stavu) — koeficient stlačenia (1/15 namiesto
  // pôvodných 0.12) je dopočítaný z rovnakej rovnice, takže sa cik-cak a kôš
  // hýbu presne súhlasne, bez medzery aj bez prekrytia. Vďaka tomu už netreba
  // mechanizmus na začiatku schovávať priehľadnosťou — je vidno hneď od štartu.
  const scissorStyle = {
    transformOrigin: "210px 480px",
    transform: risen ? "scaleY(1)" : "scaleY(0.0667)",
    transition: rise,
  };
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
      <svg width="210" height="280" viewBox="0 0 420 560">
        <ellipse cx="210" cy="532" rx="140" ry="12" fill="#000" opacity="0.08" />
        <g style={scissorStyle}>
          <line x1="115" y1="480" x2="305" y2="381" stroke="var(--accent)" strokeWidth="12" strokeLinecap="round" />
          <line x1="305" y1="480" x2="115" y2="381" stroke="var(--accent)" strokeWidth="12" strokeLinecap="round" />
          <line x1="115" y1="381" x2="305" y2="282" stroke="var(--accent-dark)" strokeWidth="12" strokeLinecap="round" />
          <line x1="305" y1="381" x2="115" y2="282" stroke="var(--accent-dark)" strokeWidth="12" strokeLinecap="round" />
          <line x1="115" y1="282" x2="305" y2="183" stroke="var(--accent)" strokeWidth="12" strokeLinecap="round" />
          <line x1="305" y1="282" x2="115" y2="183" stroke="var(--accent)" strokeWidth="12" strokeLinecap="round" />
          <line x1="115" y1="183" x2="305" y2="84" stroke="var(--accent-dark)" strokeWidth="12" strokeLinecap="round" />
          <line x1="305" y1="183" x2="115" y2="84" stroke="var(--accent-dark)" strokeWidth="12" strokeLinecap="round" />
        </g>
        <rect x="90" y="472" width="240" height="52" rx="6" fill="var(--text)" />
        <rect x="266" y="462" width="34" height="26" rx="2" fill="#2b2b2b" />
        <circle cx="283" cy="475" r="4" fill="var(--accent)" />
        <circle cx="150" cy="526" r="22" fill="var(--text)" />
        <circle cx="150" cy="526" r="9" fill="#666" />
        <circle cx="270" cy="526" r="22" fill="var(--text)" />
        <circle cx="270" cy="526" r="9" fill="#666" />
        <g style={{ transform: risen ? "translateY(0px)" : "translateY(369.6px)", transition: rise }}>
          <rect x="90" y="56" width="240" height="28" rx="4" fill="var(--text)" />
          <rect x="90" y="10" width="8" height="50" fill="var(--text)" />
          <rect x="322" y="10" width="8" height="50" fill="var(--text)" />
          <rect x="90" y="10" width="240" height="8" fill="var(--accent)" />
          <rect x="90" y="34" width="240" height="5" fill="var(--accent)" />
          <rect x="170" y="10" width="8" height="50" fill="var(--text)" />
          <rect x="242" y="10" width="8" height="50" fill="var(--text)" />
        </g>
        {/* Obsluha stroja — malý pozdrav pri načítavaní appky, stojí bokom a
            kýva jednou rukou (nezávisle od zdvihu, len sa tu spolu s ním
            zjaví). */}
        <g>
          <line x1="350" y1="504" x2="344" y2="552" stroke="var(--text)" strokeWidth="9" strokeLinecap="round" />
          <line x1="363" y1="504" x2="372" y2="552" stroke="var(--text)" strokeWidth="9" strokeLinecap="round" />
          <line x1="344" y1="462" x2="331" y2="491" stroke="var(--text)" strokeWidth="9" strokeLinecap="round" />
          <rect x="342" y="458" width="29" height="48" rx="8" fill="var(--text)" />
          <rect x="340" y="494" width="32" height="8" fill="var(--accent)" />
          <line x1="345" y1="459" x2="371" y2="502" stroke="var(--accent)" strokeWidth="5" strokeLinecap="round" />
          <line x1="371" y1="459" x2="345" y2="502" stroke="var(--accent)" strokeWidth="5" strokeLinecap="round" />
          <circle cx="356" cy="440" r="19" fill="var(--text)" />
          <path d="M331 437 A 26 27 0 0 1 382 437 Z" fill="var(--accent)" />
          {/* Ruka (mascot-wave-arm) je posunutá o 16px doľava oproti pôvodnej
              polohe — pri kývaní ±16° sa špička ruky vychyľuje až ~44px od
              ramena, a pri pôvodnej polohe (pivot pri x=387) to pri výkyve
              vpravo prestrelilo cez pravý okraj viewBoxu (0 0 420 560) a
              appka ruku odrezala. Tu už má rezervu. */}
          <g className="mascot-wave-arm">
            <line x1="371" y1="462" x2="400" y2="424" stroke="var(--text)" strokeWidth="9" strokeLinecap="round" />
            <circle cx="400" cy="424" r="6" fill="var(--text)" />
          </g>
        </g>
      </svg>
      {label && <div className="label-font" style={{ color: "var(--text-dim)", fontSize: 13 }}>{label}</div>}
    </div>
  );
}

/* ---------------------------------------------------------
   Error boundary — ak niečo v platforme zlyhá pri vykresľovaní,
   zachytí to platforma sama (namiesto toho, aby to "vypadlo" von).
--------------------------------------------------------- */
class AppErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, info) {
    console.error("mateco-app crashed:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: 40, fontFamily: "Barlow, sans-serif", maxWidth: 640, margin: "40px auto" }}>
          <h2 style={{ color: "#E30613", marginBottom: 12 }}>Nastala neočakávaná chyba</h2>
          <p style={{ marginBottom: 16, color: "#333" }}>
            Platforma narazila na chybu pri vykresľovaní tejto obrazovky. Skúste to znova — ak sa to opakuje, dajte mi vedieť presne, čo ste práve robili.
          </p>
          <button
            onClick={() => this.setState({ hasError: false, error: null })}
            style={{
              padding: "9px 18px",
              background: "#E30613",
              color: "#fff",
              border: "none",
              borderRadius: 6,
              fontFamily: "Barlow, sans-serif",
              fontWeight: 600,
              cursor: "pointer",
              marginBottom: 16,
            }}
          >
            Skúsiť znova
          </button>
          <details style={{ whiteSpace: "pre-wrap", fontSize: 12, color: "#777" }}>
            <summary style={{ cursor: "pointer" }}>Technický detail</summary>
            {String(this.state.error && this.state.error.stack ? this.state.error.stack : this.state.error)}
          </details>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function App() {
  return (
    <AppErrorBoundary>
      <DispatcherApp />
    </AppErrorBoundary>
  );
}
